# Stories for albums 952–1001, the last batch (book numbers after the White Album was inserted as #134; long format:
# three paragraphs + a listening tip, ~220–230 words per story, three picks with ~12-word notes). Original Hebrew;
# facts checked on the web, uncertain ones softened. Used by tools/batches/build_952_1001.py;
# later edits: python3 tools/apply_stories.py stories_952_1001
STORIES = {}
def add(n, story, picks): STORIES[n] = {'story': story, 'picks': picks}

add(952, [
'''הפליימינג ליפס מאוקלהומה סיטי הם להקה שמנגנת כבר משנות השמונים, ובסוף שנות התשעים הפכו מלהקת רעש מוזרה לאחת הלהקות הכי אהובות של האינדי, עם The Soft Bulletin (אלבום 892). Yoshimi Battles the Pink Robots, שיצא ב־2002, ממשיך באותו כיוון אבל מוסיף הרבה יותר צלילים אלקטרוניים: מכונות תופים, סינתיסייזרים ותכנותים, לצד גיטרות אקוסטיות. הזמר וויין קוין, עם הקול הדק והשביר שלו, כתב כאן שירים פשוטים במבט ראשון שמסתתרות בהם שאלות גדולות על החיים ועל המוות.''',
'''כמה מהשירים בתחילת האלבום מספרים סיפור קטן ומשעשע על יושימי, נערה יפנית שלומדת קראטה ונלחמת ברובוטים ורודים ורעים. בתפקיד יושימי צועקת ושרה מוזיקאית יפנית אמיתית בשם יושימי, מלהקת הרעש היפנית בורדומס. אבל מהר מאוד מתברר שהרובוטים הם בעצם משל: לשיר על מחלה, על פחד ועל אנשים שאנחנו עלולים לאבד. Fight Test הפותח שואל מתי צריך להילחם ומתי לוותר, ו־Do You Realize?? הוא שיר חגיגי ומלא כלי מיתר, שמזכיר לנו שכל מי שאנחנו מכירים ימות יום אחד, ובכל זאת שמח מאוד. האלבום נגמר בקטע כלי יפה בשם Approaching Pavonis Mons by Balloon, שזכה בפרס גראמי.''',
'''Yoshimi הפך לאלבום המצליח ביותר של הלהקה ופתח לה דלת לקהל רחב. Do You Realize?? נבחר מאוחר יותר לשיר הרוק הרשמי של מדינת אוקלהומה, וההופעות של הלהקה, עם קונפטי, בלונים ותחפושות של חיות, הפכו לאגדה. האלבום הראה שאפשר לעשות פופ פסיכדלי מלא דמיון ומשחק, ועדיין לגעת בנושאים הכי כבדים שיש.''',
'''שמעו קודם את Do You Realize?? בווליום גבוה, ואחר כך חזרו להתחלה וקחו את הסיפור על יושימי כמו סרט מצויר. אם אהבתם את The Soft Bulletin (אלבום 892), השוו בין השניים: שם יותר כלי מיתר ותזמורת, וכאן יותר מכונות ומשחק.''',
], [
('Fight Test', 'שיר פתיחה קליט ששואל מתי צריך להילחם על מה שאוהבים, ומתי לוותר.'),
('Yoshimi Battles the Pink Robots, Pt. 1', 'שיר אקוסטי מתוק על הנערה יושימי והרובוטים הוורודים, מלא חן והומור.'),
('Do You Realize??', 'שיר חגיגי ומרגש על כך שהחיים קצרים, עם כלי מיתר ומקהלה.'),
])

add(953, [
'''דאבס הם שלישייה ממנצ׳סטר: הזמר והבסיסט ג׳ימי גודווין והתאומים ג׳ז ואנדי ויליאמס. בשנות התשעים הם ניגנו מוזיקת ריקודים בשם אחר, ורק אחר כך עברו לרוק רחב ונוגה. אלבום הבכורה שלהם, Lost Souls (אלבום 903), היה אפל ומהורהר. The Last Broadcast, שיצא ב־2002, פתוח יותר, אופטימי יותר וגדול יותר, והגיע למקום הראשון במצעד הבריטי. הוא נשמע כמו נסיעה בלילה בעיר תעשייה ישנה, כשהאורות של הבוקר כבר מתחילים להופיע באופק.''',
'''הצליל של דאבס בנוי משכבות: גיטרות מהדהדות, תופים עמוקים וחזקים, פסנתר, כלי מיתר ולפעמים גם מקהלה. There Goes the Fear, הלהיט הגדול של האלבום, נמשך כמעט שבע דקות ונגמר בחגיגת תופים לטינית שמחה ומפתיעה. Pounding הוא שיר מהיר ודוהר, עם תופים שלא עוצרים לרגע, ו־Caught by the River הוא שיר שקט ונוגע ללב על חבר שעובר תקופה קשה. Satellites מסתיים במקהלת גוספל, ו־Words פותח את האלבום בהבטחה גדולה. גם השירים העצובים נשמעים כאן כמו תקווה, וזה הקסם של הלהקה.''',
'''The Last Broadcast הפך את דאבס לאחת הלהקות הבריטיות הגדולות של תחילת שנות האלפיים, והאלבום היה מועמד לפרס מרקורי. הוא ממשיך מסורת ארוכה של להקות ממנצ׳סטר, מהסטון רוזס (אלבום 647) ועד אואזיס (אלבום 768), שהפכו את העיר האפורה לסיפור רומנטי, אבל הוא עושה את זה בשקט ובלי להתרברב.''',
'''זה אלבום טוב במיוחד לנסיעה ארוכה או להליכה בערב, כשהשמש שוקעת. שמעו את There Goes the Fear עד הסוף, כי התופים בסיום הם ההפתעה הכי יפה באלבום.''',
], [
('There Goes the Fear', 'השיר הגדול של האלבום, שנגמר בחגיגת תופים לטינית שמחה ומפתיעה מאוד.'),
('Pounding', 'שיר מהיר ודוהר עם תופים חזקים, כמו רכבת שלא עוצרת בתחנות.'),
('Caught by the River', 'שיר שקט ומרגש על חבר שזקוק לעזרה, עם גיטרות מהדהדות ויפות.'),
])

add(954, [
'''מיסי אליוט מווירג׳יניה היא אחת הראפריות והיוצרות החשובות של ההיפ הופ, ויחד עם המפיק טימבלנד, חבר ילדות שלה, היא שינתה את הצליל שלו כבר בסוף שנות התשעים (אלבום 840). Under Construction יצא בסוף 2002, ובעקבות שנה עצובה: שתי חברות קרובות שלה מעולם המוזיקה, הזמרת אליה וליסה "לפט איי" לופס מ־TLC, נהרגו בתאונות. מיסי החליטה לעשות אלבום שמחזיר את ההיפ הופ לימים התמימים של שנות השמונים, כשכולם עוד רקדו ברחוב, בלי מלחמות בין ראפרים.''',
'''הצליל של טימבלנד חסכוני ומשוגע בו בזמן: תופים חדים, באסים עמוקים, וצלילים מוזרים כמו קולות של פילים. Work It, הלהיט הגדול של האלבום, מלא משחקי מילים, וכולל שורה שמיסי שרה הפוך, כשההקלטה מתנגנת לאחור. השיר הגיע למקום השני במצעד האמריקאי ונשאר שם שבועות ארוכים. Back in the Day, עם ג׳יי זי (אלבום 940), הוא שיר נוסטלגי על הימים הראשונים של ההיפ הופ, ו־Gossip Folks, עם הראפר לודקריס, צוחק על רכילות ועל אנשים שמדברים מאחורי הגב. יש גם קטעי מעבר קצרים שמזכירים את ההומור של מיסי, ואת האהבה שלה לריקוד.''',
'''Under Construction הפך לאלבום הנמכר ביותר של מיסי אליוט, ואחד האלבומים החשובים של ראפרית אישה. הוא הראה שאפשר להיות מצחיקה, חכמה וחדשנית בו זמנית, ושהיפ הופ יכול לחגוג את העבר שלו בלי להישמע מיושן.''',
'''שמעו את Work It ונסו לתפוס את השורה ההפוכה. אחר כך שמעו את Back in the Day, ותבינו למה מיסי התגעגעה לימים שבהם ההיפ הופ היה בעיקר מסיבה.''',
], [
('Work It', 'הלהיט הגדול, מלא משחקי מילים, קולות של פילים ושורה אחת ששרים הפוך.'),
('Gossip Folks', 'שיר שמח ומהיר שצוחק על אנשים שמדברים מאחורי הגב, עם לודקריס.'),
('Back in the Day', 'שיר נוסטלגי עם ג׳יי זי, על הימים הראשונים והתמימים של ההיפ הופ.'),
])

add(955, [
'''ברוס ספרינגסטין, הזמר מניו ג׳רזי שהכרנו כאן כבר כמה פעמים (אלבומים 335, 409, 511 ו־546), לא הקליט אלבום אולפן עם להקת אי סטריט שלו שמונה עשרה שנה. אחרי פיגועי 11 בספטמבר 2001 הוא חזר אליה, ו־The Rising, שיצא בקיץ 2002, הוא התגובה שלו לאסון. לפי הסיפור, אדם זר עצר אותו ברחוב כמה ימים אחרי הפיגוע ואמר לו: "אנחנו צריכים אותך". רבים מהשירים מדברים על כבאים, על משפחות שאיבדו יקירים ועל הניסיון להמשיך לחיות.''',
'''למרות הנושא הכבד, זה לא אלבום קודר. המפיק ברנדן או׳בריאן נתן ללהקה צליל רחב ומודרני, עם גיטרות, עוגב, כינור ומקהלות גוספל. The Rising, שיר הנושא, מספר על כבאי שעולה במדרגות של בניין בוער, ומסתיים בשירה משותפת שנשמעת כמו תפילה. Lonesome Day הוא שיר רוק שמח ומתגעגע, ו־Mary's Place הוא שיר מסיבה עם כלי נשיפה. My City of Ruins, שנכתב עוד לפני הפיגועים על העיר אסברי פארק שהתרוקנה, קיבל משמעות חדשה ונשמע עכשיו כמו קריאה לקום מההריסות. ב־Worlds Apart מצטרף זמר קוואלי פקיסטני, ושני עולמות נפגשים בשיר אחד.''',
'''The Rising זכה בפרס גראמי לאלבום הרוק הטוב ביותר, והחזיר את ספרינגסטין למרכז. הוא הראה שמוזיקת רוק יכולה לעזור לעם שלם להתאבל, בלי סיסמאות ובלי שנאה, רק עם אמפתיה, אמונה ותקווה.''',
'''שמעו את The Rising ואת My City of Ruins ברצף. אם אהבתם את Born to Run (אלבום 335), תשמעו כאן את אותה להקה, שלושים שנה אחר כך, בוגרת יותר אבל עם אותו להט.''',
], [
('The Rising', 'כבאי שעולה במדרגות של בניין בוער, ושירה משותפת שנשמעת כמו תפילה.'),
('Lonesome Day', 'שיר רוק מתגעגע ושמח בו בזמן, עם כינור ומקהלה ברקע.'),
('My City of Ruins', 'שיר גוספל איטי שקורא לקום מההריסות, ונשמע אחרי הפיגועים כמו תפילה.'),
])

add(956, [
'''כריסטינה אגילרה מפנסילבניה התחילה כילדה בתוכנית הטלוויזיה של דיסני "מועדון מיקי מאוס", יחד עם בריטני ספירס וג׳סטין טימברלייק (אלבום 959). בסוף שנות התשעים היא הפכה לכוכבת פופ צעירה עם Genie in a Bottle, אבל הרגישה שהתדמית המתוקה הזו לא מייצגת אותה. Stripped, שיצא ב־2002, הוא אלבום שבו היא "מתפשטת" מהתדמית הישנה: היא כתבה בעצמה חלק גדול מהשירים, ומדברת בו על המשפחה, על מערכות יחסים קשות, על נשים ועל הביטחון שלה בעצמה.''',
'''האלבום מגוון מאוד: פופ, רוקנרול, סול, היפ הופ ובלדות גדולות לפסנתר. הכוכב האמיתי הוא הקול של אגילרה, חזק וגמיש, שמזכיר זמרות סול גדולות כמו אטה ג׳יימס. Beautiful, בלדה שכתבה לינדה פרי, אומר לכל מי שמרגיש לא מספיק טוב שהוא יפה כמו שהוא, וזכה בפרס גראמי. Fighter הוא שיר רוק עם גיטרה חשמלית, שמודה למי שפגע בה כי זה הפך אותה לחזקה יותר. Dirrty, עם הראפר רדמן, היה פרובוקטיבי מאוד בזמנו, עם קליפ שהסעיר את כולם, ו־Can't Hold Us Down, עם ליל קים, קורא לנשים לא לשתוק.''',
'''Stripped הפך את אגילרה מכוכבת נוער לזמרת בוגרת ומוערכת. Beautiful הפך להמנון לבני נוער ולקהילה הגאה, ועד היום שרים אותו בתחרויות שירה. האלבום הוכיח שגם כוכבת פופ מתוכנתת יכולה לקחת שליטה על הקריירה שלה.''',
'''האלבום ארוך, ולא כל השירים באותה רמה. התחילו מ־Beautiful ומ־Fighter, ואחר כך הקשיבו ל־The Voice Within, בלדה שבה הקול שלה מגיע לשיאים מדהימים.''',
], [
('Beautiful', 'בלדה פשוטה ומרגשת לכל מי שמרגיש לא מספיק טוב, שזכתה בגראמי.'),
('Fighter', 'שיר רוק עם גיטרה חשמלית, שמודה למי שפגע בה כי זה חיזק אותה.'),
('Dirrty', 'שיר מסיבה פרובוקטיבי עם הראפר רדמן, שהסעיר את כולם בזמנו.'),
])

add(957, [
'''הרוטס מפילדלפיה הם להקת היפ הופ מיוחדת: במקום דגימות ומכונות, הם מנגנים בכלים אמיתיים. המתופף קוואסטלאב והראפר בלאק ת׳וט הקימו את הלהקה עוד בתיכון, ובשנות התשעים הם הפכו לאחת הלהקות המוערכות בהיפ הופ. Phrenology, שיצא בסוף 2002, הוא האלבום הכי שאפתני שלהם. שמו לקוח מתורה ישנה ומופרכת שניסתה לקבוע את אופיו של אדם לפי צורת הגולגולת שלו, ועל העטיפה מצויר ראש עם חלקים ממוספרים.''',
'''האלבום קופץ בין סגנונות בלי פחד: היפ הופ, סול, פאנק, רוק כבד ואפילו ג׳אז חופשי. Rock You נשמע כמו רוק כבד, ו־Break You Off הוא בלדת סול רכה ואיטית עם הזמר מיוזיק סולצ׳ייל. The Seed 2.0 הוא שיר רוקנרול קופצני שבו הזמר קודי צ׳סנאט שר על גיטרה חשמלית, והוא הפך ללהיט הגדול של האלבום. Water הוא יצירה של עשר דקות על חבר להקה שהתמכר לסמים, שמתחיל כהיפ הופ ומתפרק לרעש ניסיוני. בלאק ת׳וט מרפרף בין מילים חכמות, הומור וזעם, וקוואסטלאב שומר על הכל בתופים מדויקים להפליא.''',
'''Phrenology הוכיח שהיפ הופ יכול להיות מגוון ומפתיע כמו כל סוג מוזיקה אחר. הרוטס המשיכו מאז להצליח, ובהמשך הפכו ללהקה הקבועה של תוכנית האירוח של ג׳ימי פאלון, והיו לאחת הלהקות הכי מוכרות באמריקה.''',
'''האלבום מלא קטעים קצרים ומעברים, אז כדאי לשמוע אותו ברצף. שמעו את The Seed 2.0 ואת Break You Off אחד אחרי השני, כדי להבין כמה רחב הטווח של הלהקה.''',
], [
('The Seed 2.0', 'רוקנרול קופצני ושמח עם הזמר קודי צ׳סנאט, הלהיט הגדול של האלבום.'),
('Break You Off', 'בלדת סול רכה ואיטית, עם הזמר מיוזיק סולצ׳ייל ותופים עדינים במיוחד.'),
('Water', 'יצירה ארוכה על חבר שהתמכר לסמים, שמתחילה כהיפ הופ ומתפרקת לרעש.'),
])

add(958, [
'''בק הנסן מלוס אנג׳לס הוא אמן שאוהב לשנות כיוון. ב־Odelay (אלבום 814) הוא ערבב היפ הופ, רוק, פאנק וקאנטרי לקולאז׳ שמח ומשוגע. אבל ב־2002, אחרי שהסתיימה מערכת יחסים ארוכה, הוא הוציא את Sea Change, ששמו פירושו "שינוי עמוק", והוא אלבום שקט, איטי ועצוב מאוד. במקום משחקי מילים והומור, בק שר כאן בפשטות על לב שבור, על בדידות ועל הניסיון להמשיך הלאה. רבים רואים בו את האלבום הכי טוב שלו.''',
'''את האלבום הפיק נייג׳ל גודריץ׳, המפיק של רדיוהד (אלבומים 838 ו־910), ואת כלי המיתר עיבד אביו של בק, דייוויד קמפבל. הצליל עשוי מגיטרות אקוסטיות, פדאל סטיל של קאנטרי, פסנתר ותזמורת כלי מיתר רחבה. The Golden Age הפותח מתאר נסיעה במדבר בלילה, Lost Cause הוא שיר עדין על הרגע שבו מבינים שאין מה להציל, ו־Paper Tiger מזכיר את כלי המיתר הדרמטיים של סרז׳ גינסבורג (אלבום 226). Round the Bend נשמע כמעט כמו שיר של ניק דרייק (אלבום 191), ו־Guess I'm Doing Fine הוא שיר מושלם לימים אפורים.''',
'''Sea Change הראה צד חדש ואמיתי של בק, והפך לאחד מאלבומי הפרידה הגדולים. הוא דומה במובן מסוים ל־Blood on the Tracks של בוב דילן (אלבום 342), אלבום פרידה אחר שבו אמן מוכר מוריד את המסכה.''',
'''זה אלבום ללילה, לאוזניות ולשקט. אל תחפשו בו להיטים, אלא תנו לו לעבור לאט. אחר כך, לשם השוואה, שמעו את Guero של בק (אלבום 1000), שבו הוא חוזר לשמחה ולקולאז׳.''',
], [
('The Golden Age', 'שיר פתיחה איטי ויפה, כמו נסיעה במדבר בלילה עם החלון פתוח.'),
('Lost Cause', 'שיר עדין ופשוט על הרגע שבו מבינים שאין עוד מה להציל.'),
('Paper Tiger', 'כלי מיתר דרמטיים ובס עמוק, שמזכירים את סרז׳ גינסבורג בשנות השבעים.'),
])

add(959, [
'''ג׳סטין טימברלייק מטנסי התחיל כילד בתוכנית "מועדון מיקי מאוס", יחד עם בריטני ספירס וכריסטינה אגילרה (אלבום 956), ובסוף שנות התשעים היה הזמר הראשי של להקת הבנים אנ׳סינק, אחת הלהקות הנמכרות בעולם. Justified, אלבום הסולו הראשון שלו, יצא בסוף 2002, והראה שהוא רוצה להיות יותר מעוד כוכב של להקת בנים. הוא עבד עם שני צוותי ההפקה החמים ביותר של אותה תקופה: הנפטונז, כלומר פארל ויליאמס וצ׳אד הוגו, וטימבלנד, המפיק של מיסי אליוט (אלבום 954).''',
'''ההשראה הגדולה כאן היא מייקל ג׳קסון של Off the Wall (אלבום 450): פופ רקיד עם פאנק, גיטרות חדות, קולות פלסטו גבוהים וכפיים. Like I Love You נפתח בגיטרה אקוסטית ספרדית ובקצב מקפץ, ו־Rock Your Body הוא שיר דיסקו שמח שלפי הסיפור נכתב במקור בשביל ג׳קסון עצמו. Cry Me a River, בהפקת טימבלנד, הוא שיר אפל ודרמטי עם מקהלה גרגוריאנית, ביטבוקס וגשם, על אהבה שנבגדה. רבים קישרו אותו לפרידה המפורסמת של טימברלייק מבריטני ספירס. Señorita הוא שיר קליל עם פסנתר חשמלי, שבו טימברלייק מחלק את הקהל לבנים ולבנות ששרים יחד.''',
'''Justified זכה בפרס גראמי לאלבום הפופ הקולי הטוב ביותר, ופתח לטימברלייק קריירה ארוכה כזמר, רקדן ושחקן. הוא גם הראה כמה ההפקות של הנפטונז וטימבלנד שינו את הפופ של תחילת שנות האלפיים, עם צלילים חסכוניים, תופים חדים ובאסים עמוקים.''',
'''שמעו את Rock Your Body ואחר כך את Don't Stop 'til You Get Enough מ־Off the Wall (אלבום 450), ותשמעו בדיוק מאיפה זה בא. ואם אתם אוהבים דרמה, שמעו את Cry Me a River באוזניות, עם כל הפרטים הקטנים.''',
], [
('Cry Me a River', 'שיר דרמטי על אהבה שנבגדה, עם מקהלה, ביטבוקס וגשם ברקע.'),
('Rock Your Body', 'שיר דיסקו שמח שנשמע כמו מחווה ישירה למייקל ג׳קסון של שנות השבעים.'),
('Like I Love You', 'גיטרה ספרדית, קצב מקפץ וקול פלסטו, בהפקה של הנפטונז.'),
])

add(960, [
'''הוויינס הם להקה מסידני שבאוסטרליה, שהזמר והגיטריסט שלה, קרייג ניקולס, היה צעיר, ביישן ובלתי צפוי. ב־2002 התקשורת הבריטית חיפשה את "הדבר הבא" אחרי הסטרוקס (אלבום 935) והווייט סטרייפס (אלבום 938), והוויינס היו חלק מאותו גל של להקות "THE" שהחזירו את הגיטרות למרכז. Highly Evolved, אלבום הבכורה שלהם, הוקלט בלוס אנג׳לס עם המפיק רוב שנאפ, והגיע לטופ 10 בבריטניה. הלהקה אפילו הופיעה על שער מגזין רולינג סטון עם הכותרת "הרוק חזר".''',
'''הצליל של הוויינס משלב שני עולמות: הצעקות והגיטרות הרועשות של נירוונה (אלבום 686), והמלודיות הפסיכדליות והמתוקות של הביטלס בסוף שנות השישים. Get Free, הלהיט הגדול, הוא שיר קצר וזועם של שתי דקות, שבו ניקולס צורח בכל הכוח. שיר הנושא, Highly Evolved, קצר עוד יותר, ומתחיל את האלבום כמו פיצוץ. אבל יש כאן גם צד שקט ויפה: Autumn Shade הוא שיר אקוסטי רך, כמעט חלומי, ו־Homesick מתגעגע ומלא הרמוניות. Outtathaway הוא עוד שיר מהיר ומלא אנרגיה. המעבר בין צעקות לשקט יוצר תחושה של מישהו שמצב הרוח שלו משתנה בכל רגע.''',
'''Highly Evolved היה אחד האלבומים שסימנו את תחיית הרוק של תחילת שנות האלפיים. לוויינס לא הייתה קריירה ארוכה בצמרת: ההופעות של ניקולס היו כאוטיות, ובהמשך אובחן אצלו תסמונת אספרגר, מה שהסביר חלק מהקשיים. אבל האלבום הראשון נשאר רגע של אנרגיה נקייה.''',
'''זה אלבום קצר, מעט יותר משלושים דקות, אז שמעו אותו ברצף. נסו לשים לב איך שירים רועשים ושקטים מתחלפים, כמו גלים.''',
], [
('Highly Evolved', 'שיר פתיחה קצר ומתפוצץ, שמציג את הלהקה בתוך פחות משתי דקות.'),
('Get Free', 'הלהיט הזועם והקצר, עם צעקות וגיטרות רועשות בסגנון נירוונה.'),
('Autumn Shade', 'שיר אקוסטי רך וחלומי, שמראה את הצד העדין והמלודי של הלהקה.'),
])

add(961, [
'''ההייבז הם להקת רוק מעיירה קטנה בשם פגרשטה שבשוודיה, שמופיעה תמיד בחליפות שחורות־לבנות תואמות. הזמר שלהם, האולין׳ פלה אלמקוויסט, ידוע כאחד הפרונטמנים הכי אנרגטיים ושחצנים בכיף שיש. Your New Favourite Band, שיצא באנגליה בסוף 2001, הוא בעצם אוסף של שירים משני האלבומים הראשונים שלהם, שכמעט אף אחד מחוץ לשוודיה לא שמע. השם, "הלהקה האהובה החדשה שלכם", הוא בדיוק סוג הבדיחה השחצנית של הלהקה, והוא התגלה כנכון: האוסף הגיע לטופ 10 הבריטי.''',
'''המוזיקה היא רוקנרול גראז׳ מהיר, קצר ורועש, בהשראת להקות פאנק ורוק של שנות השישים והשבעים, כמו הסטוג׳ס (אלבום 172). כמעט אף שיר לא עובר שלוש דקות. Hate to Say I Told You So, הלהיט הגדול, בנוי על ריף גיטרה פשוט וקליט ועל תופים שלא עוצרים, ואלמקוויסט צועק בו כמו מטיף. Main Offender ו־Die, All Right! מהירים וחדים עוד יותר. את רוב השירים חתום אדם מסתורי בשם רנדי פיצסימונס, שלפי הלהקה הוא המנהל והכותב שלה, אבל אף אחד לא ראה אותו מעולם, ורבים מאמינים שמדובר בשם בדוי של אחד הנגנים.''',
'''Your New Favourite Band הפך את ההייבז לאחת הלהקות המרכזיות בתחיית הרוק של תחילת שנות האלפיים, לצד הסטרוקס והווייט סטרייפס (אלבומים 935 ו־938). ההופעות שלהם, מלאות קפיצות, צעקות וחליפות, הפכו לשם דבר.''',
'''זה אוסף של כחצי שעה, בלי רגע אחד של מנוחה. שמעו אותו בקול רם, ורצוי בזמן שאתם עושים משהו שדורש אנרגיה. Hate to Say I Told You So הוא נקודת ההתחלה המושלמת.''',
], [
('Hate to Say I Told You So', 'ריף גיטרה פשוט וקליט, תופים דוהרים וזמר שצועק כמו מטיף.'),
('Main Offender', 'שיר רוקנרול מהיר וחד, עם פזמון שקל מאוד לצעוק יחד.'),
('Die, All Right!', 'פאנק קצר וזועם, שעובר כמו רכבת בפחות משלוש דקות.'),
])

add(962, [
'''רדיוהד מאוקספורד הם אחת הלהקות החשובות של התקופה, והכרנו אותם כאן כבר כמה פעמים (אלבומים 797, 838, 910 ו־929). אחרי Kid A ו־Amnesiac, שבהם התרחקו מהגיטרות לטובת מוזיקה אלקטרונית, Hail to the Thief, שיצא ב־2003, מחבר את שני העולמות. הם הקליטו אותו מהר, בתוך שבועיים בלבד באולפן בלוס אנג׳לס, עם המפיק הקבוע נייג׳ל גודריץ׳, והשאירו בו את התחושה של הופעה חיה. השם מתייחס לבחירות לנשיאות ארצות הברית בשנת 2000, שרבים טענו שנגנבו.''',
'''יש כאן ארבעה עשר שירים, ולכל אחד גם שם שני בסוגריים, כמו כותרת משנה. 2 + 2 = 5, הפותח, מתחיל בשקט ומתפוצץ באמצע לגיטרות זועמות, בהשראת ספרו של ג׳ורג׳ אורוול "1984". There There הוא שיר עם תופים רבים ומהדהדים ששלושה נגנים מתופפים יחד, וגיטרה שמגיעה לשיא מרגש. Sail to the Moon, שתום יורק כתב לבנו הקטן, הוא בלדה לפסנתר יפה במיוחד. Go to Sleep נשמע כמעט כמו שיר פולק, ו־Myxomatosis הוא קטע אלקטרוני מטורף עם סינתיסייזר מעוות. השילוב בין גיטרות ומכונות נשמע כאן טבעי.''',
'''Hail to the Thief נחשב לאלבום הארוך והפחות מהודק של רדיוהד, אבל רבים אוהבים אותו בגלל זה: הוא חם, אנושי ומלא רעיונות. הוא היה גם האלבום האחרון של הלהקה בחברת התקליטים הגדולה שלה, לפני שהחלו להוציא מוזיקה בעצמם.''',
'''האלבום ארוך, יותר משחמישים דקות. אם אתם חדשים, התחילו מ־There There ומ־Sail to the Moon, ואחר כך חזרו להתחלה ושמעו את הכל ברצף.''',
], [
('2 + 2 = 5', 'מתחיל בשקט מתוח ומתפוצץ באמצע, בהשראת הספר "1984" של ג׳ורג׳ אורוול.'),
('There There', 'תופים רבים ומהדהדים וגיטרה שמגיעה לשיא מרגש, אחד השירים הגדולים שלהם.'),
('Sail to the Moon', 'בלדה לפסנתר שתום יורק כתב לבנו הקטן, עדינה ויפה במיוחד.'),
])

add(963, [
'''איימי ויינהאוס נולדה בלונדון למשפחה יהודית, וגדלה על תקליטי הג׳אז שאהבו בבית: פרנק סינטרה (אלבום 1), דינה וושינגטון, שרה ווהן (אלבום 18). Frank, אלבום הבכורה שלה, יצא ב־2003, כשהייתה רק בת עשרים. השם הוא מחווה לסינטרה, וגם מילה באנגלית שפירושה "גלוי לב", וזה בדיוק מה שהיא: כנה, חצופה ומצחיקה. היא כתבה או שותפה בכתיבת כל השירים, ושרה בקול עמוק ובוגר שנשמע כמו של זמרת ג׳אז מבוגרת ומנוסה.''',
'''האלבום מערבב ג׳אז, סול, היפ הופ ורגאיי, בהפקה של סלאם רמי, שעבד עם הפוג׳יז. המילים הן הסוד: ויינהאוס כותבת על גברים, על אהבה ועל עצמה בלי שום עידון, עם הומור וסלנג לונדוני. Stronger Than Me, הסינגל הראשון, הוא תלונה על בן זוג חלש שלא מתנהג כמו גבר, והוא זכה בפרס אייבור נובלו, פרס חשוב לכותבי שירים בבריטניה. Take the Box הוא שיר פרידה עצוב על ארגז של חפצים שמחזירים לבן הזוג, ו־You Sent Me Flying מתחיל בשקט עם פסנתר ומתפתח לסיפור על אהבה שלא נענתה. In My Bed חצוף ומלא קצב.''',
'''Frank היה מועמד לפרס מרקורי והציג לעולם קול נדיר. שלוש שנים אחר כך ויינהאוס הפכה לכוכבת עולמית עם Back to Black, ומתה ב־2011, בגיל עשרים ושבע בלבד. Frank נשאר האלבום הקליל והשמח שלה, לפני שהכל השתבש.''',
'''שמעו את האלבום עם כוס יין בערב, כמו בבר ג׳אז. אחר כך שמעו את In the Wee Small Hours של סינטרה (אלבום 1), ותבינו איך הכל התחיל.''',
], [
('Stronger Than Me', 'תלונה מצחיקה וחריפה על בן זוג חלש, שזכתה בפרס חשוב לכותבי שירים.'),
('Take the Box', 'שיר פרידה עצוב על ארגז של חפצים שמחזירים לבן הזוג לשעבר.'),
('You Sent Me Flying', 'מתחיל בשקט עם פסנתר ומתפתח לסיפור עצוב על אהבה שלא נענתה.'),
])

add(964, [
'''קלקסיקו היא להקה מטוסון שבאריזונה, ליד הגבול עם מקסיקו. ג׳ואי ברנס וג׳ון קונברטינו הכירו כנגנים בלהקה ג׳איינט סאנד (אלבום 923), ובמשך השנים בנו צליל משלהם, שנשמע כמו פסקול של סרט מערבון שמתרחש במדבר. השם לקוח מהעיר קלקסיקו בקליפורניה, שיושבת על הגבול, מול העיר המקסיקנית מקסיקלי. Feast of Wire, שיצא ב־2003, הוא האלבום הכי מגוון ומוערך שלהם.''',
'''המוזיקה של קלקסיקו משלבת חצוצרות מריאצ׳י מקסיקניות, גיטרות של מערבונים בסגנון אניו מוריקונה, אקורדיון, ויברפון, ג׳אז, ורוק אינדי שקט. ברנס שר בקול רך ועייף, כמעט לוחש. Quattro (World Drifts In) הוא שיר יפה ונוגה עם חצוצרות מתנפנפות, ו־Sunken Waltz הוא ואלס קטן ומתוק. Black Heart הוא שיר אפל ודרמטי עם כלי מיתר, כמו סצנה מסרט אימה במדבר. כמה מהשירים מדברים על הגבול, על מהגרים שחוצים את המדבר ועל העולם שמשתנה סביבם. יש כאן גם רגעים של ג׳אז אלקטרוני ניסיוני, שמראים שהלהקה לא נעולה בסגנון אחד.''',
'''Feast of Wire הפך את קלקסיקו לאחת הלהקות המוערכות של האמריקנה, המוזיקה האמריקאית המסורתית שמתחדשת. הם הוכיחו שאפשר לחבר בין מקסיקו לארצות הברית, בין המערב הפרוע לג׳אז, ולמצוא מקום יפה באמצע.''',
'''זה אלבום מושלם לנסיעה ארוכה בנוף פתוח, או לערב חם בקיץ. אם אהבתם את Chore of Enchantment של ג׳איינט סאנד (אלבום 923), תמצאו כאן את אותו מדבר, בצבעים חמים יותר.''',
], [
('Sunken Waltz', 'ואלס קטן ומתוק, עם אקורדיון וגיטרה, כמו ריקוד בכיכר של עיירה.'),
('Quattro (World Drifts In)', 'שיר נוגה עם חצוצרות מריאצ׳י, על עולם שמשתנה סביבנו.'),
('Black Heart', 'שיר אפל ודרמטי עם כלי מיתר, כמו סצנה מסרט מערבון.'),
])

add(965, [
'''הדארקנס היא להקה מהעיירה לוסטופט שבמזרח אנגליה, והזמר שלה, ג׳סטין הוקינס, הוא דמות שאי אפשר לשכוח: הוא שר בקול פלסטו גבוה מאוד ולובש בגדים צמודים ומנצנצים בסגנון שנות השבעים. ב־2003, כשכולם ניגנו אינדי רציני, הדארקנס החזירו את הרוק הכבד, הצבעוני והמוגזם של שנות השבעים והשמונים. Permission to Land, אלבום הבכורה שלהם, הגיע למקום הראשון בבריטניה, נמכר ביותר ממיליון עותקים בבריטניה וזכה בשלושה פרסי בריט.''',
'''המוזיקה לוקחת השראה מקווין (אלבום 345), מתין ליזי (אלבום 412) ומ־AC/DC (אלבום 427): ריפים של גיטרה כפולה, סולואים ארוכים, תופים חזקים ופזמונים גדולים. I Believe in a Thing Called Love, הלהיט הגדול, מלא הומור ושמחה, וכולל סולו גיטרה מטורף וקולות פלסטו מטפסים. Get Your Hands off My Woman פותח את האלבום בצעקה, ו־Growing on Me הוא שיר קליט וחביב. Black Shuck מספר על כלב שחור ומפחיד מהאגדות של מזרח אנגליה, ו־Love Is Only a Feeling הוא בלדת רוק מוגזמת להפליא. הכל עשוי ברצינות גמורה ובקריצה בו בזמן.''',
'''Permission to Land הראה שגם אחרי שנים של רוק אלטרנטיבי רציני, הקהל מתגעגע לכיף ולהגזמה של הרוק הישן. הדארקנס לא שמרו על ההצלחה לאורך זמן, אבל ב־2003 הם היו הלהקה הכי מדוברת באנגליה.''',
'''שמעו את I Believe in a Thing Called Love בקול רם, ואל תתביישו לשיר עם הפלסטו. אחר כך שמעו את A Night at the Opera של קווין (אלבום 345), ותבינו מאיפה הכל בא.''',
], [
('I Believe in a Thing Called Love', 'הלהיט הגדול, מלא הומור, סולו גיטרה מטורף וקולות פלסטו מטפסים.'),
('Black Shuck', 'שיר רוק על כלב שחור ומפחיד מהאגדות של מזרח אנגליה.'),
('Love Is Only a Feeling', 'בלדת רוק מוגזמת ומרגשת, עם סולו גיטרה ארוך בסגנון שנות השבעים.'),
])

add(966, [
'''הווייט סטרייפס מדטרויט היו צמד: ג׳ק וייט בגיטרה ובשירה, ומג וייט בתופים. הם הציגו את עצמם כאח ואחות, למרות שבעצם היו נשואים פעם. ב־White Blood Cells (אלבום 938) הם הפכו לכוכבים, ו־Elephant, שיצא באביב 2003, הפך אותם לאחת הלהקות הגדולות בעולם. הם הקליטו אותו בלונדון, בתוך כשבועיים, באולפן שבו השתמשו רק בציוד ישן משנות השישים ולפניהן, בלי מחשבים. המטרה הייתה צליל גולמי, חם ואמיתי.''',
'''הצליל פשוט ועוצמתי: גיטרה, תופים וקול, ושום דבר מיותר. Seven Nation Army, שפותח את האלבום, בנוי על ריף שנשמע כמו גיטרה בס, אבל הוא בעצם גיטרה רגילה שעוברת דרך מכשיר שמנמיך את הצליל באוקטבה. הריף הזה הפך לאחד המפורסמים בהיסטוריה, וקהלים באצטדיוני כדורגל ברחבי העולם שרים אותו עד היום. Ball and Biscuit הוא בלוז ארוך של שבע דקות עם סולואים פרועים, ו־The Hardest Button to Button קצבי ומדויק. I Just Don't Know What to Do with Myself הוא גרסה רועשת לשיר של ברט בכרך, ו־In the Cold, Cold Night שרה מג בקול שקט.''',
'''Elephant זכה בפרס גראמי לאלבום האלטרנטיבי הטוב ביותר, והפך לאחד מאלבומי הרוק החשובים של שנות האלפיים. הוא הוכיח שאפשר להגיע להמונים עם שני אנשים, ציוד ישן ואהבה גדולה לבלוז.''',
'''שמעו את Seven Nation Army ונסו לשמוע אותו כאילו אתם לא מכירים אותו. אחר כך הקשיבו ל־Ball and Biscuit באוזניות, ותשמעו את כל הפרטים הקטנים של הגיטרה.''',
], [
('Seven Nation Army', 'הריף המפורסם, שנשמע כמו בס ושרים אותו באצטדיונים בכל העולם.'),
('Ball and Biscuit', 'בלוז ארוך ופרוע של שבע דקות, עם סולואים מטורפים של ג׳ק וייט.'),
('The Hardest Button to Button', 'תופים מדויקים וריף קצבי, אחד השירים הכי קליטים של הצמד.'),
])

add(967, [
'''דיזי רסקל, ששמו האמיתי דילן מילס, גדל בבאו שבמזרח לונדון, שכונה ענייה וקשוחה. הוא התחיל לעשות מוזיקה עוד בבית הספר, על מחשב בחדר המוזיקה, ובגיל שבע עשרה כבר הופיע ברדיו הפיראטי של לונדון. Boy in da Corner, אלבום הבכורה שלו, יצא ב־2003, כשהיה בן תשע עשרה בלבד, וזכה בפרס מרקורי, הפרס החשוב ביותר למוזיקה בריטית. דיזי היה אז הזוכה הצעיר ביותר בתולדות הפרס.''',
'''המוזיקה נקראת גרייים, סגנון לונדוני שנולד מתוך מוזיקת ריקודים בריטית והיפ הופ: ביטים קרים, מהירים ושבורים, צלילים אלקטרוניים צורמים כמו של משחק מחשב ישן, ובס עמוק. דיזי ראפ בקצב מהיר מאוד, במבטא לונדוני כבד, על החיים בשכונה: אלימות, עוני, בני נוער מבולבלים ולחץ חברתי. I Luv U הוא שיח חריף בין נער לנערה, עם ביט שנשמע כמו אזעקה. Fix Up, Look Sharp בנוי על תופים מתוך שיר רוק ישן, והוא הלהיט הקליט ביותר. Sittin' Here פותח את האלבום בשקט מהורהר, כשדיזי מסתכל על השכונה שלו ושואל לאן כל זה הולך.''',
'''Boy in da Corner הפך את הגרייים לסגנון מוכר בכל העולם, ופתח את הדלת לדור שלם של ראפרים בריטים. רבים רואים בו אלבום חשוב כמו האלבומים הראשונים של הסטריטס (אלבום 994): דיוקן של צעירים בלונדון, בקול שלהם.''',
'''המבטא והסלנג לא תמיד קלים להבנה, אבל לא צריך להבין כל מילה. שמעו את Sittin' Here ואת Fix Up, Look Sharp, ותנו לביטים לעשות את העבודה.''',
], [
("Sittin' Here", 'פתיחה שקטה ומהורהרת, נער שמסתכל על השכונה ושואל לאן כל זה הולך.'),
('I Luv U', 'שיח חריף בין נער לנערה, עם ביט צורם שנשמע כמו אזעקה.'),
('Fix Up, Look Sharp', 'הלהיט הקליט, בנוי על תופים משיר רוק ישן ועל ראפ מהיר.'),
])

add(968, [
'''קינגס אוף לאון הם משפחה: שלושה אחים, קיילב, נייתן וג׳ארד פולוויל, ובן דודם מתיו. אביהם היה מטיף שנסע ברחבי הדרום האמריקאי, והילדים גדלו במכונית ובכנסיות, עם מוזיקת גוספל. כשהאב עזב את הכנסייה, האחים עברו לנאשוויל והתחילו לנגן רוק. Youth & Young Manhood, אלבום הבכורה שלהם, יצא ב־2003, והפיק אותו איתן ג׳ונס, בנו של המפיק המפורסם גלין ג׳ונס. הם הצליחו קודם כל בבריטניה, הרבה לפני שארצות הברית שמה לב אליהם.''',
'''הצליל משלב רוק דרומי של שנות השבעים עם האנרגיה הגולמית של הסטרוקס (אלבום 935): גיטרות מחוספסות, תופים פשוטים וקולו הייחודי של קיילב, שמושך מילים, ממלמל ונשמע לפעמים כמו מישהו שמנסה לא לבכות. Molly's Chambers הוא שיר קצר וקליט עם ריף גיטרה מקפץ, ו־Red Morning Light פותח את האלבום במהירות ובהתלהבות. California Waiting הוא שיר מתגעגע עם פזמון גדול, ו־Holy Roller Novocaine הוא בלוז איטי שמזכיר את הכנסיות של הילדות. Trani הוא שיר ארוך ואיטי שבו הלהקה מראה כמה היא יכולה לבנות מתח. יש באלבום גם שירים על נשים, משקאות ובעיות.''',
'''Youth & Young Manhood הציג להקה צעירה ופראית, ששנים אחר כך הפכה לאחת הלהקות הגדולות בעולם, עם שירים שמתנגנים באצטדיונים. רבים עדיין חושבים שהאלבום הראשון, הגולמי, הוא הטוב ביותר שלהם.''',
'''שמעו את Molly's Chambers, ואחר כך את Aha Shake Heartbreak (אלבום 998), האלבום השני שיצא שנה אחר כך, ותשמעו איך הלהקה התפתחה.''',
], [
('Red Morning Light', 'פתיחה מהירה ונלהבת, עם גיטרות מחוספסות וקול ממלמל ומיוחד.'),
("Molly's Chambers", 'שיר קצר וקליט עם ריף גיטרה מקפץ, הסינגל הראשון של הלהקה.'),
('California Waiting', 'שיר מתגעגע עם פזמון גדול, על חלום לברוח למקום אחר.'),
])

add(969, [
'''הת׳רילס הם להקה מדבלין שבאירלנד, אבל המוזיקה שלהם חולמת על מקום אחר לגמרי: קליפורניה של סוף שנות השישים. חברי הלהקה בילו קיץ בסן דייגו כשהיו צעירים, ומאז לא הפסיקו להתגעגע לחופים, לשמש ולכבישים הפתוחים. So Much for the City, אלבום הבכורה שלהם, יצא ב־2003. השם, "כל כך הרבה בשביל העיר", מבטא בדיוק את הרצון לברוח מהעיר הגשומה ולחפש קיץ נצחי. האלבום הצליח מאוד בבריטניה ובאירלנד, והיה מועמד לפרס מרקורי.''',
'''המוזיקה מושפעת מהביץ׳ בויז (אלבומים 52 ו־61), מהבירדס (אלבום 57) ומלהקות פולק רוק של קליפורניה: הרמוניות קוליות, גיטרות מצלצלות, מפוחית, בנג׳ו וכלי מיתר. הזמר קונור דיסי שר בקול עדין ומתגעגע. Santa Cruz (You're Not That Far) הוא שיר שמש מקסים, ו־Big Sur, הלהיט הגדול, מצטט בפזמון שורה מתוך שיר הנושא של הסדרה "המונקיז" (אלבום 85). One Horse Town נשמע כמו מערבון קטן ומתוק, ו־Don't Steal Our Sun הוא שיר שמח עם בנג׳ו. שמות השירים מלאים במקומות אמריקאיים: סנטה קרוז, ביג סור, סן דייגו. הכל נשמע קליל, אבל יש מתחת לשמש גם עצב של מי שיודע שהקיץ ייגמר.''',
'''So Much for the City הוא אלבום צנוע ומתוק, שלא שינה את עולם המוזיקה, אבל הזכיר לרבים כמה יפה יכול להיות פופ של שנות השישים. הוא נשאר ההצלחה הגדולה ביותר של הלהקה.''',
'''זה אלבום מושלם לבוקר של קיץ או לנסיעה לחוף. שמעו את Big Sur ונסו לזהות את השורה מהמונקיז, ואחר כך את Pet Sounds (אלבום 61), כדי לשמוע מאיפה כל הקיץ הזה מגיע.''',
], [
("Santa Cruz (You're Not That Far)", 'שיר שמש מקסים עם הרמוניות קוליות, על מקום קרוב ורחוק בו בזמן.'),
('Big Sur', 'הלהיט הגדול, עם פזמון שמצטט שורה מתוך שיר הנושא של המונקיז.'),
('One Horse Town', 'שיר קטן ומתגעגע על עיירה קטנה, כמו סצנה מסרט מערבון מתוק.'),
])

add(970, [
'''ייה ייה ייהז היא שלישייה מניו יורק: הזמרת קארן או, הגיטריסט ניק זינר והמתופף בריאן צ׳ייס. אין להם בסיסט, והגיטרה של זינר ממלאת את כל החלל. בתחילת שנות האלפיים הם היו חלק מאותה סצנה ניו יורקית שהוציאה את הסטרוקס (אלבום 935), וההופעות שלהם הפכו לאגדה בזכות קארן או, שצרחה, התגלגלה על הבמה, לבשה תלבושות מטורפות וירקה מים. Fever to Tell, אלבום הבכורה, יצא ב־2003, והפיק אותו דייוויד סיטק מלהקת טי וי און דה רדיו (אלבום 992).''',
'''רוב האלבום רועש, מהיר ופרוע: גיטרות חותכות, תופים חזקים וקארן או שצועקת, נאנחת ומצחקקת. Rich ו־Date with the Night פותחים בהתפרצות של אנרגיה, ו־Pin הוא שיר פאנק קצר וקליט. אבל הרגע הגדול מגיע לקראת הסוף: Maps הוא שיר אהבה שקט, פגיע ויפה מאוד, שבו קארן או שרה שוב ושוב "חכה, הם לא אוהבים אותך כמו שאני אוהבת אותך". לפי הדיווחים, היא כתבה אותו לאנגוס אנדרו, הזמר של להקת לייארס (אלבום 993), שהיה אז בן הזוג שלה. השיר הפך ללהיט ענק, והקליפ, שבו היא בוכה באמת, נשאר בזיכרון. Y Control ו־Modern Romance סוגרים את האלבום בעצב שקט.''',
'''Fever to Tell הפך את ייה ייה ייהז לאחת הלהקות החשובות של סצנת הרוק הניו יורקית, וקארן או הפכה לדמות השראה עבור דור של זמרות. Maps נחשב היום לאחד משירי האהבה הגדולים של שנות האלפיים.''',
'''שמעו את האלבום מההתחלה, כדי להרגיש את ההפתעה כש־Maps מגיע אחרי כל הרעש. אחר כך, למי שאוהב חיבורים, שמעו את They Were Wrong, So We Drowned של לייארס (אלבום 993).''',
], [
('Maps', 'שיר אהבה שקט ופגיע, אחד מהשירים היפים ביותר של שנות האלפיים.'),
('Date with the Night', 'התפרצות של אנרגיה, עם קארן או שצועקת ומצחקקת על גיטרה חותכת.'),
('Y Control', 'שיר עצוב וקצבי, שמראה עוד צד של הלהקה לקראת סוף האלבום.'),
])

add(971, [
'''אאוטקאסט מאטלנטה, הצמד של ביג בוי ואנדרה 3000, כבר הוכיחו את עצמם עם Stankonia (אלבום 928). ב־2003 הם עשו משהו חריג: אלבום כפול, שבו כל אחד מהם הקליט אלבום סולו משלו, ושניהם יצאו יחד תחת שם הלהקה. Speakerboxxx הוא האלבום של ביג בוי, ו־The Love Below הוא של אנדרה. התוצאה הייתה אחת ההצלחות הגדולות בתולדות ההיפ הופ: מיליוני עותקים, ופרס גראמי לאלבום השנה, הישג נדיר מאוד לאלבום היפ הופ.''',
'''שני החצאים שונים מאוד. Speakerboxxx של ביג בוי הוא היפ הופ דרומי, מהיר ופאנקי, עם כלי נשיפה, ביטים חזקים ומסרים פוליטיים. The Way You Move, עם הזמר סליפי בראון, הוא שיר ריקוד חם ושמח. The Love Below של אנדרה הוא כמעט לא היפ הופ בכלל: הוא שר, מנגן ומערבב פאנק, ג׳אז, פופ ורוק בסגנון של פרינס (אלבום 538), בסיפור על אדם שמחפש אהבה. Hey Ya!, הלהיט שלו, הוא שיר פופ מהיר ושמח, עם שורה מפורסמת על לנער את התמונה כמו פולארויד, שבעצם מספר על זוגות שנשארים יחד רק מתוך הרגל. Roses הוא שיר מצחיק ומרושע על בחורה יהירה. Hey Ya! ו־The Way You Move הגיעו שניהם למקום הראשון במצעד האמריקאי, אחד אחרי השני.''',
'''Speakerboxxx/The Love Below הוכיח שהיפ הופ יכול להיות כל דבר: פאנק, פופ, ג׳אז ואפילו מחזמר. הוא גם הראה שני אמנים שונים מאוד, שכל אחד מהם הלך בדרכו, אבל עדיין משלים את השני.''',
'''זה אלבום ארוך מאוד, יותר משעתיים, עם קטעי מעבר רבים. אין צורך לשמוע את הכל: התחילו מ־The Way You Move ומ־Hey Ya!, ואחר כך בחרו חצי אחד ושמעו אותו ברצף.''',
], [
('Hey Ya!', 'שיר פופ שמח ומהיר, שבעצם מספר על זוגות שנשארים יחד מתוך הרגל.'),
('The Way You Move', 'שיר ריקוד חם של ביג בוי, עם כלי נשיפה והזמר סליפי בראון.'),
('Roses', 'שיר מצחיק ומרושע של אנדרה על בחורה יהירה, עם פזמון שקשה לשכוח.'),
])

add(972, [
'''50 סנט, ששמו האמיתי קרטיס ג׳קסון, גדל בשכונת קווינס בניו יורק בילדות קשה. ב־2000, כשניסה לפרוץ כראפר, נורה תשע פעמים מול בית סבתו, ושרד. חברת התקליטים הגדולה שלו נטשה אותו, אבל הוא המשיך להוציא שירים בעצמו, עד שאמינם (אלבומים 895 ו־921) שמע אותו והחתים אותו יחד עם דוקטור דרה (אלבום 718). Get Rich or Die Tryin׳, אלבום הבכורה הרשמי שלו, יצא בתחילת 2003, ומכר כמעט מיליון עותקים בשבוע הראשון, אחד הפתיחות הגדולות בתולדות ההיפ הופ.''',
'''הקול של 50 סנט רגוע, עצלני וכמעט מזמזם, שונה מאוד מהצעקות של ראפרים אחרים, והוא שר את הפזמונים בעצמו, בלחן קליט. In da Club, בהפקת דוקטור דרה, הוא שיר מסיבה פשוט עם ביט מינימליסטי, שהפך לאחד השירים המושמעים ביותר של העשור, ופותח במשפט "גו שורטי, זה יום ההולדת שלך". 21 Questions הוא שיר אהבה רך, שבו הוא שואל את בת הזוג אם הייתה נשארת איתו גם אם היה עני. Many Men (Wish Death) הוא שיר אפל על הניסיון להתנקש בחייו, ו־P.I.M.P. הוא להיט ריקוד קליל. רוב השירים מדברים על רחוב, אלימות וכסף, בלי הרבה עידון.''',
'''Get Rich or Die Tryin׳ היה האלבום הנמכר ביותר בארצות הברית ב־2003, והפך את 50 סנט לאחד הראפרים הגדולים בעולם. הוא גם סימן את השיא של גל הגנגסטה ראפ שהתחיל עם The Chronic (אלבום 718), וסגר אותו בהצלחה מסחרית ענקית.''',
'''הנושאים קשים לפעמים, אבל הביטים של דרה ואמינם הם תענוג. שמעו את In da Club ואת 21 Questions, כדי לשמוע את שני הצדדים של 50 סנט: הקשוח והרך.''',
], [
('In da Club', 'שיר מסיבה עם ביט מינימליסטי של דוקטור דרה, אחד השירים הגדולים של העשור.'),
('21 Questions', 'שיר אהבה רך, ששואל אם היא הייתה נשארת איתו גם בלי כסף.'),
('Many Men (Wish Death)', 'שיר אפל ומרגש על הניסיון להתנקש בחייו, עם פזמון עצוב.'),
])

add(973, [
'''המארס וולטה נולדו מתוך להקת פוסט־הארדקור בשם את דה דרייב אין מאל פאסו שבטקסס, שהתפרקה בשיא הצלחתה. הזמר סדריק ביקסלר־זבאלה והגיטריסט עומר רודריגס־לופס רצו לעשות משהו שאפתני הרבה יותר, והקימו להקה חדשה. De-Loused in the Comatorium, אלבום הבכורה, יצא ב־2003, בהפקת ריק רובין, ועם פלי מהרד הוט צ׳ילי פפרז בבס. זה אלבום קונספט, שמבוסס על סיפור של חבר קרוב שלהם, אמן מאל פאסו שמת: אדם בשם סרפין טקסט, שנופל לתרדמת ומבלה שבוע בעולם חלומות מוזר ומפחיד.''',
'''המוזיקה משלבת פרוגרסיב רוק של שנות השבעים, כמו קינג קרימזון (אלבום 168) ולד זפלין (אלבום 157), עם פאנק, סלסה וג׳אז פיוז׳ן. השירים ארוכים, מלאים חילופי קצב פתאומיים, סולואי גיטרה מטורפים ותופים מהירים מאוד, וביקסלר־זבאלה שר בקול גבוה וחודר, במילים מסובכות ומלאות מילים מומצאות. Inertiatic ESP הוא פתיחה מתפוצצת ומהירה, ו־Televators הוא שיר שקט ונוגה יותר, כמעט בלדה. Cicatriz ESP נמשך יותר משתים עשרה דקות, ובאמצעו יש קטע ארוך של צלילים מרחפים ושקטים. Drunkship of Lanterns רוקד בקצב לטיני.''',
'''De-Loused in the Comatorium החזיר את הפרוגרסיב רוק לחיים בשנות האלפיים, והראה שגם להקה צעירה יכולה לנגן בווירטואוזיות ובשאפתנות של שנות השבעים. הוא הפך לאחד האלבומים האהובים על נגנים ומוזיקאים.''',
'''זה אלבום תובעני, שצריך לשמוע באוזניות ובקשב מלא. התחילו מ־Televators, השיר הנגיש ביותר, ואחר כך נסו את הכל ברצף, כמו סרט.''',
], [
('Inertiatic ESP', 'פתיחה מתפוצצת, עם תופים מהירים, גיטרה מטורפת וקול גבוה וחודר.'),
('Televators', 'השיר השקט והנגיש ביותר, כמעט בלדה, עם גיטרה אקוסטית ושירה נוגה.'),
('Cicatriz ESP', 'יצירה ארוכה של יותר משתים עשרה דקות, עם קטע מרחף ומוזר באמצע.'),
])

add(974, [
'''לייטנינג בולט הם צמד מפרובידנס שברוד איילנד: בריאן צ׳יפנדייל בתופים ובשירה, ובריאן גיבסון בגיטרה בס. הם התחילו לנגן באמצע שנות התשעים, כשהיו סטודנטים לאמנות, וגרו במחסן ישן שהפך למרכז של סצנת אמנות ורעש. במקום להופיע על במה, הם מציבים את הציוד על הרצפה, באמצע הקהל, שמקיף אותם מכל הצדדים. Wonderful Rainbow, האלבום השלישי שלהם, יצא ב־2003, ונחשב לטוב ביותר שלהם.''',
'''זו מוזיקה רועשת, מהירה ועזה מאוד. צ׳יפנדייל מתופף כמעט בלי הפסקה, בקצב מטורף ובחופשיות של ג׳אז, וגיבסון מנגן על הבס ריפים חוזרים שנשמעים כמו גיטרה חשמלית מעוותת, ולפעמים כמו מכונה. הקול של צ׳יפנדייל עובר דרך מיקרופון קטן שהוא מחזיק בתוך הפה, מתחת למסכה שהוא לובש, ולכן המילים כמעט לא נשמעות, והן הופכות לעוד צליל. Dracula Mountain הוא קטע בלתי פוסק עם ריף מהפנט, גם בתוך כל הרעש מסתתרות מנגינות קטנות ומשחקיות, כמעט כמו שירי ילדים מעוותים.''',
'''Wonderful Rainbow הפך את לייטנינג בולט לאחת הלהקות החשובות של רוק הרעש, והשפיע על להקות רבות בכל העולם. הוא הוכיח ששני אנשים עם בס ותופים יכולים להישמע כמו תזמורת שלמה של רעש.''',
'''זה לא אלבום קל, והוא מתאים בעיקר למי שאוהב רעש ועוצמה. נסו להקשיב לתופים בלבד בכל שיר, ותופתעו כמה הם מדויקים בתוך הכאוס. ואם נבהלתם, נסו קודם שיר אחד בלבד, ואחר כך חזרו.''',
], [
('Dracula Mountain', 'ריף בס מהפנט וחוזר, ותופים שלא עוצרים לרגע, כמו טירוף מבוקר.'),
('2 Towers', 'בס ותופים שבונים יחד קיר עצום של רעש, כמו סערה.'),
('Wonderful Rainbow', 'שיר הנושא, שבו מסתתרת בתוך הרעש מנגינה קטנה ומשחקית.'),
])

add(975, [
'''רופוס ויינרייט נולד במשפחה של מוזיקאים: אביו הוא זמר הפולק לאודון ויינרייט השלישי, ואמו היא קייט מקגריגל, מהצמד האהוב קייט ואנה מקגריגל. הוא גדל במונטריאול, התאהב באופרה כנער, ושר בקול עשיר ונוגה ובסגנון דרמטי שמזכיר זמרי קברט. Want One, שיצא ב־2003, הוא האלבום השלישי שלו, והחלק הראשון מתוך זוג: החצי השני, Want Two (אלבום 995), יצא שנה אחר כך. לפני האלבום הזה ויינרייט עבר תקופה קשה של התמכרות, והאלבום נשמע כמו חזרה לחיים.''',
'''המוזיקה עשירה ומפוארת: פסנתר, תזמורת כלי מיתר, כלי נשיפה, מקהלות וקולות שכבות, בהפקה של מריוס דה פריס. Oh What a World, הפותח, מתחיל בציטוט מתוך ה"בולרו" של ראוול, ובונה בהדרגה צעדה תזמורתית מצחיקה ועצובה. I Don't Know What It Is הוא שיר גדול ומתגעגע על תחושת חוסר מנוחה, ו־Vibrate מתוק וקטן. Dinner at Eight הוא אולי השיר הכי אישי: שיחה קשה בין ויינרייט לאביו, על יחסים מסובכים בין אבא לבן, שנגמרת בפסנתר שקט. Go or Go Ahead הוא בלדה דרמטית עם גיטרה חשמלית. Beautiful Child עליז וקצבי, ו־14th Street הוא שיר שמח על ניו יורק.''',
'''Want One נחשב לאחד האלבומים הטובים של ויינרייט, והראה שאפשר לחבר בין אופרה, קברט ופופ בלי להישמע מיושן. הוא פתח את הדרך לפרויקטים גדולים יותר שלו, כולל אופרה שלמה שכתב בהמשך.''',
'''שמעו את Want One ואת Want Two (אלבום 995) אחד אחרי השני, כמו שתי מערכות של אותו מחזה. התחילו מ־Dinner at Eight, ושימו לב למילים.''',
], [
('Oh What a World', 'פתיחה תזמורתית עם ציטוט מה"בולרו" של ראוול, מצחיקה ועצובה בו בזמן.'),
('Dinner at Eight', 'שיחה קשה ומרגשת בין ויינרייט לאביו, שנגמרת בפסנתר שקט.'),
('Go or Go Ahead', 'בלדה דרמטית וגדולה עם גיטרה חשמלית, אחד הרגעים העזים באלבום.'),
])

add(976, [
'''סיזור סיסטרז היא להקה מניו יורק, שנולדה בסצנת המועדונים הגאה של העיר בתחילת שנות האלפיים. הזמר ג׳ייק שירס, הזמרת אנה מטרוניק והמוזיקאי בייבידדי הובילו להקה צבעונית, תיאטרלית ומלאת הומור. דווקא באמריקה לא שמו אליהם לב בהתחלה, אבל בבריטניה הם הפכו לתופעה: אלבום הבכורה שלהם, שיצא ב־2004, היה האלבום הנמכר ביותר בבריטניה באותה שנה, וזכה בשלושה פרסי בריט.''',
'''המוזיקה היא מסיבה של שנות השבעים: דיסקו, גלאם רוק ופופ, בהשראת אלטון ג׳ון (אלבום 289), הבי ג׳יז (אלבום 147) ודייוויד בואי. שירס שר הרבה בקול פלסטו גבוה, והשירים מלאים פסנתר, כלי מיתר וקצב ריקודים. Take Your Mama הוא שיר שמח עם פסנתר, על בן שלוקח את אמו לבלות בעיר, כדי להראות לה את העולם שלו. Laura קופצני ומצחיק, ו־Mary הוא בלדה מרגשת לחברה קרובה. הרגע המפורסם ביותר הוא גרסת הדיסקו ל־Comfortably Numb של פינק פלויד (אלבום 448): השיר האפל והאיטי הפך כאן לשיר ריקודים בפלסטו, בסגנון הבי ג׳יז. Filthy/Gorgeous הוא שיר מסיבה פרוע.''',
'''האלבום הראה שאפשר לחגוג את הדיסקו והגלאם בלי ציניות, ובשמחה גלויה. הוא הפך את סיזור סיסטרז לאחת הלהקות הגדולות באירופה, ונתן קול ונראות ללהקה גאה מוצהרת במרכז הזרם הפופולרי.''',
'''שמעו את Comfortably Numb שלהם, ומיד אחריו את המקור מ־The Wall (אלבום 448). ההבדל מצחיק ומרתק. ואז שמעו את Take Your Mama ותתחילו לרקוד.''',
], [
('Take Your Mama', 'שיר שמח עם פסנתר, על בן שלוקח את אמו לבלות בעיר הגדולה.'),
('Comfortably Numb', 'השיר האפל של פינק פלויד, שהפך כאן לשיר ריקודים בפלסטו.'),
('Mary', 'בלדה חמה ומרגשת לחברה קרובה, עם פסנתר ושירה גבוהה ורכה.'),
])

add(977, [
'''מוריסי, הזמר לשעבר של הסמית׳ס (אלבומים 558, 584 ו־599), הוציא אלבומי סולו מוערכים בסוף שנות השמונים ובשנות התשעים (אלבומים 630, 712 ו־766). אבל אחרי 1997 הוא נעלם כמעט לגמרי: חברות התקליטים לא רצו בו, והוא עבר לגור בלוס אנג׳לס. You Are the Quarry, שיצא ב־2004, היה הקאמבק שלו אחרי שבע שנים, והוא הצליח מעבר לכל הציפיות: הגיע למקום השני בבריטניה, והיה אחד האלבומים הנמכרים ביותר שלו. על העטיפה מוריסי מחזיק תת־מקלע, בפוזה של גנגסטר מסרט ישן.''',
'''המפיק ג׳רי פין נתן למוריסי צליל רוק חזק ומלוטש. השירים חוזרים לכל הנושאים שלו: בדידות, אנגליה, אמריקה, דת ואהבה שלא נענית, אבל עם הומור חריף וביטחון חדש. Irish Blood, English Heart הוא שיר זועם ומהיר על הזהות האנגלית־אירית שלו ועל הפוליטיקה הבריטית, והגיע למקום השלישי במצעד. First of the Gang to Die הוא שיר קליט ושמח, על נער לטיני בשם הקטור שהיה הראשון בחבורה שלו שנהרג, ומוריסי הפך אותו לגיבור טרגי. America Is Not the World מבקר את ארצות הברית, ו־I Have Forgiven Jesus הוא שיר מצחיק ועצוב על אלוהים שנתן לו אהבה בלי שיהיה למי לתת אותה. Let Me Kiss You רך ומתגעגע.''',
'''You Are the Quarry החזיר את מוריסי לצמרת, והראה שהקול והמילים שלו לא איבדו דבר מכוחם. הוא גם חשף אותו לקהל צעיר חדש, במיוחד בקרב קהילה לטינית גדולה בלוס אנג׳לס שאוהבת אותו מאוד.''',
'''שמעו את First of the Gang to Die ואת Irish Blood, English Heart, ואחר כך השוו ל־Viva Hate (אלבום 630), כדי לשמוע איך מוריסי התבגר בחמש עשרה שנה.''',
], [
('Irish Blood, English Heart', 'שיר זועם ומהיר על זהות אנגלית ואירית, ועל פוליטיקה בריטית.'),
('First of the Gang to Die', 'שיר קליט ושמח על נער לטיני שהפך כאן לגיבור טרגי.'),
('I Have Forgiven Jesus', 'שיר מצחיק ועצוב על אהבה שאין למי לתת אותה.'),
])

add(978, [
'''ביורק מאיסלנד הייתה כבר אמנית מוערכת מאוד (אלבומים 632, 750 ו־931), ותמיד אהבה לנסות דברים חדשים. ב־Medúlla, שיצא ב־2004, היא החליטה לעשות אלבום כמעט כולו מקולות אנושיים: בלי גיטרות, בלי כלי מיתר, וכמעט בלי כלים בכלל. השם, בלטינית, פירושו "לשד" או "גרעין", החלק הפנימי והעמוק של משהו. ביורק כתבה את האלבום אחרי שנולדה בתה, ורצתה לחזור למשהו גופני, עתיק ובסיסי, משהו שקדם לשפה ולטכנולוגיה.''',
'''הצלילים כאן עשויים ממקהלות, משירה שכבתית של ביורק עצמה, ומאמני ביטבוקס שמחקים בפה תופים ובס. הזמרת האינואיטית טניה טגאק מביאה שירת גרון מסורתית מוזרה ומרתקת, ומשתתפים גם הזמר מייק פטון ורוברט ווייאט (אלבום 325). Oceanía, שנכתב לטקס הפתיחה של האולימפיאדה באתונה ב־2004 וביורק שרה אותו שם, מדבר מנקודת המבט של האוקיינוס, שמסתכל על בני האדם שיצאו ממנו. Who Is It הוא שיר קצבי וחם, עם מקהלה וביטבוקס, ו־Triumph of a Heart הוא שיר שמח ומשוגע שבו כל הצלילים, גם הבס והתופים, באים מפיות של אנשים.''',
'''Medúlla הוא אחד הניסויים האמיצים ביותר של אמנית פופ גדולה. הוא הוכיח שהקול האנושי לבדו יכול ליצור עולם שלם של צלילים, ופתח את האוזניים של רבים לשירת גרון, לביטבוקס ולמקהלות.''',
'''זה אלבום מוזר, אז תנו לו זמן. שמעו באוזניות ונסו לנחש איזה צליל בא מאיזה פה. התחילו מ־Who Is It ומ־Triumph of a Heart, הנגישים ביותר.''',
], [
('Oceanía', 'שיר מטקס האולימפיאדה, מנקודת המבט של האוקיינוס שמסתכל על בני האדם.'),
('Who Is It', 'שיר קצבי וחם, עם מקהלה וביטבוקס במקום תופים וכלים.'),
('Triumph of a Heart', 'שיר שמח ומשוגע, שבו כל הצלילים, גם הבס, באים מפיות של אנשים.'),
])

add(979, [
'''מיילו, ששמו האמיתי מיילס מקאינס, גדל באי סקיי שבסקוטלנד, למד באוקספורד, ועשה מוזיקה במחשב נייד בחדר השינה שלו בגלזגו. Destroy Rock & Roll, אלבום הבכורה שלו, יצא ב־2004 בחברת תקליטים קטנה שהקים בעצמו, וכמעט בלי תקציב. האלבום התפשט לאט, מפה לאוזן, וב־2005 כבר היה אחד מאלבומי הדאנס המצליחים בבריטניה. רבים השוו אותו ל־Moon Safari של אייר (אלבום 875) ול־Homework של דאפט פאנק (אלבום 851).''',
'''הסוד של מיילו הוא דגימות מפופ רך ונשכח של שנות השבעים והשמונים, שהוא חותך, מאט ומערבב עם ביטים של האוס. התוצאה נשמעת חמימה, שמחה ומעט נוסטלגית, כמו זיכרון של קיץ. Drop the Pressure, הלהיט הגדול, בנוי על משפט אחד שחוזר שוב ושוב על ביט מתגבר, והפך להמנון במועדונים. In My Arms משלב דגימות משני להיטי פופ של שנות השמונים, ובהם Bette Davis Eyes של קים קארנס, לשיר אחד מתוק ורקיד. שיר הנושא מבוסס על הקלטה של קול שמקריא רשימה ארוכה של שמות זמרים ולהקות משנות השמונים, כאילו מדובר בקללה שצריך לגרש, ומיילו הופך אותה לבדיחה רקידה.''',
'''Destroy Rock & Roll הראה שאפשר ליצור אלבום מצליח בחדר שינה, עם מחשב נייד, בלי אולפן ובלי חברת תקליטים גדולה, הרבה לפני שזה הפך לדבר הרגיל. הוא נשאר אלבום שמח ואהוב, מלא הומור ואהבה לפופ ישן.''',
'''זה אלבום מושלם לבוקר של שבת או לנסיעה בקיץ. שמעו את Drop the Pressure בקול רם, ואחר כך את In My Arms, ונסו לזהות את השירים הישנים שמסתתרים בתוכו.''',
], [
('Drop the Pressure', 'משפט אחד שחוזר על ביט מתגבר, וההמנון הגדול של המועדונים ב־2004.'),
('In My Arms', 'שיר מתוק ורקיד, שבנוי מדגימות של להיטי פופ משנות השמונים.'),
('Destroy Rock & Roll', 'רשימה ארוכה של שמות להקות משנות השמונים, שהפכה לבדיחה רקידה.'),
])

add(980, [
'''בריאן ויילסון, הגאון של הביץ׳ בויז, הוציא ב־1966 את Pet Sounds (אלבום 61), וכמה חודשים אחר כך את הסינגל Good Vibrations. מיד אחר כך הוא התחיל לעבוד על Smile, שהיה אמור להיות אלבום עוד יותר שאפתני, "סימפוניה לאלוהים" בלשונו, יחד עם הכותב ואן דייק פארקס. אבל הלחצים, הסמים והמחלה הנפשית שלו, וגם התנגדות חלק מחברי הלהקה, גרמו לו לנטוש את הפרויקט ב־1967. במשך שלושים ושבע שנה Smile היה האלבום האבוד המפורסם ביותר בתולדות הרוק, וחלקים ממנו הופיעו פה ושם, למשל ב־Surf's Up (אלבום 217).''',
'''ב־2004, יותר משלושים וחמש שנה אחרי שנטש אותו, ויילסון השלים סוף סוף את Smile, יחד עם פארקס ועם להקת הליווי שלו, והקליט אותו מחדש מההתחלה. הוא השמיע אותו קודם בהופעה בלונדון, שזכתה לתשואות ארוכות, ורק אחר כך הוציא את האלבום. זו יצירה אחת ארוכה, בשלושה פרקים, על אמריקה, על ההיסטוריה שלה ועל הטבע. Heroes and Villains מספר סיפור על המערב הפרוע עם הרמוניות קוליות מסובכות, Surf's Up הוא בלדה מרהיבה לפסנתר, ו־Good Vibrations, שסוגר את היצירה, קיבל כאן חיים חדשים. יש גם קטעים קצרים ומשעשעים על ירקות, על אש ועל מים, וכלים כמו בנג׳ו, צ׳לו וקולות של חיות.''',
'''Smile של 2004 הוא סיפור גאולה נדיר: אמן שחזר, אחרי עשרות שנים של מחלה ושבר, להשלים את יצירת חייו. המבקרים התלהבו, וקטע אחד מתוכו זכה בפרס גראמי. הוא הוכיח שהחלום של 1967 עדיין חי.''',
'''שמעו את Smile ברצף, כמו יצירה קלאסית, בלי לדלג. אחר כך שמעו שוב את Pet Sounds (אלבום 61), ותשמעו איך הכל המשיך משם.''',
], [
('Heroes and Villains', 'סיפור על המערב הפרוע, עם הרמוניות קוליות מסובכות ומרהיבות.'),
("Surf's Up", 'בלדה מרהיבה לפסנתר, אחד השירים היפים ביותר שבריאן ויילסון כתב.'),
('Good Vibrations', 'הלהיט הגדול מ־1966, שקיבל כאן חיים חדשים בסוף היצירה.'),
])

add(981, [
'''האיקרוס ליין היא להקה מלוס אנג׳לס, שבתחילת שנות האלפיים הייתה ידועה בעיקר בזכות ההופעות הפרועות והמסוכנות שלה, ובזכות מוניטין של להקה שמחפשת צרות. הזמר ג׳ו קרדמון והגיטריסט אהרון נורת׳, שבהמשך ניגן עם נריי אינץ׳ ניילס, הובילו להקה רועשת, זועמת וחסרת עכבות. Penance Soirée, האלבום השני שלהם, יצא ב־2004, ונחשב לטוב ביותר שלהם. השם, "נשף של חרטה", מתאים לאלבום שמשלב חטא, יופי ובלגן.''',
'''המוזיקה ממשיכה את הרוק הרועש והמסוכן של הסטוג׳ס (אלבומים 172 ו־200), עם הגיטרות הסוחפות של הרולינג סטונס, ומעט מהרעש הצורם של להקות פאנק אמריקאיות משנות השמונים. הגיטרות מעוותות ונוסרות, התופים כבדים, וקרדמון צועק, ממלמל ושר כאילו הוא על סף התמוטטות. יש כאן שירים מהירים וזועמים, אבל גם קטעים איטיים וארוכים שבונים מתח לאט ומגיעים לפיצוץ. מתחת לכל הרעש מסתתרים גם רגעים של יופי מפתיע: מלודיה של גיטרה, פזמון שנשאר בראש, או רגע שקט לפני הסערה. הכל נשמע כמו הופעה חיה בלילה אפל, במועדון קטן ומלא עשן.''',
'''Penance Soirée לא הפך ללהיט, והאיקרוס ליין נשארו להקה מוכרת בעיקר בקרב חובבי רוק רועש. אבל האלבום מעיד על הצד המסוכן של תחיית הרוק של תחילת שנות האלפיים, שלא תמיד היה מלוטש ונוח.''',
'''זה אלבום רועש וקשה, שמתאים לרגעים של כעס או אנרגיה. שמעו אותו בקול רם, ואם אהבתם, חזרו ל־Fun House של הסטוג׳ס (אלבום 200), שממנו כל זה התחיל.''',
], [
])

add(982, [
'''ארקייד פייר היא להקה ממונטריאול שבקנדה, בהובלת הזוג וין באטלר ורז׳ין שאסאן, שהם בעל ואישה. באטלר גדל בטקסס ועבר לקנדה ללמוד, ושאסאן היא בתם של מהגרים מהאיטי. Funeral, אלבום הבכורה שלהם, יצא ב־2004 בחברת תקליטים עצמאית קטנה. השם, "הלוויה", לא נבחר במקרה: בזמן ההקלטות מתו כמה מבני המשפחה של חברי הלהקה, וביניהם סבו של באטלר וסבתה של שאסאן. האלבום מלא מוות ואובדן, אבל הוא נשמע דווקא כמו חגיגה של חיים.''',
'''הלהקה גדולה, והכלים רבים: גיטרות, פסנתר, אקורדיון, כינור, צ׳לו, קסילופון, תופים וכולם שרים יחד, לפעמים צועקים. ארבעה שירים נקראים Neighborhood, ומספרים על שכונה מושלגת שבה הילדים בונים לעצמם עולם משלהם. Neighborhood #1 (Tunnels) הוא שיר אהבה על שני ילדים שחופרים מנהרה בין הבתים שלהם בשלג, ו־Neighborhood #3 (Power Out) נשמע כמו ריצה מטורפת בחושך. Wake Up הוא המנון ענק, עם מקהלה שכל הלהקה שרה בה "אוו־אוו־אוו", וקהלים בכל העולם שרים אותו בהופעות. Haiti, ששאסאן שרה בחלקו בצרפתית, מתגעגע למולדת של הוריה, ו־Rebellion (Lies) רוקד ומרד.''',
'''Funeral הפך לאחד האלבומים החשובים של שנות האלפיים, והוכיח שאלבום אינדי מחברת תקליטים קטנה יכול לכבוש את העולם. דייוויד בואי ובונו מ־U2 הפכו למעריצים, ו־Wake Up התנגן לפני הופעות של U2. האלבום פתח עידן של להקות אינדי גדולות ונלהבות, עם הרבה נגנים ושירה משותפת.''',
'''שמעו את Funeral ברצף, מ־Tunnels ועד הסוף. ואם אתם רוצים להבין למה כולם התאהבו בלהקה, שמעו את Wake Up בקול רם ונסו לא לשיר.''',
], [
('Neighborhood #1 (Tunnels)', 'שיר אהבה על שני ילדים שחופרים מנהרה בשלג בין הבתים שלהם.'),
('Wake Up', 'המנון ענק עם מקהלה של כל הלהקה, ששרים אותו בהופעות בכל העולם.'),
('Rebellion (Lies)', 'שיר רוקד ומרדני, עם תופים מתמשכים וכינור, על שקרים שמספרים לנו.'),
])

add(983, [
'''דבנדרה בנהארט נולד בטקסס, גדל בוונצואלה ובקליפורניה, והתחיל להקליט שירים על מכשירי הקלטה ביתיים זולים כשנדד בין ערים וחברים. הזמר מייקל ג׳ירה, מלהקת הסוואנס, שמע את ההקלטות שלו והוציא אותן בחברת התקליטים שלו. Rejoicing in the Hands, שיצא ב־2004, הוא האלבום הראשון שלו שהוקלט כמו שצריך, באולפן קטן, ובאותה שנה יצא גם אלבום אחות, Niño Rojo, מאותן הקלטות. בנהארט הפך לדמות מרכזית בסצנה שנקראה "פריק פולק", פולק מוזר ופסיכדלי.''',
'''המוזיקה פשוטה מאוד: גיטרה אקוסטית, לפעמים פסנתר או כלי מיתר, והקול המיוחד של בנהארט, רועד ומשתנה, לפעמים עמוק ולפעמים גבוה כמו של ילד. הוא מזכיר את מארק בולאן בתחילת דרכו, לפני טי רקס (אלבום 239), ואת זמרי הפולק של שנות השישים. השירים מלאים דמיון, הומור ומשחקי מילים: This Beard Is for Siobhan הוא שיר שמח ומצחיק עם פסנתר על הזקן שהוא מגדל, ו־A Sight to Behold הוא שיר שקט ומרגש על יופי. The Body Breaks נשמע כמו תפילה עדינה, ויש גם שירים בספרדית, לזכר הילדות בוונצואלה. הכל נשמע אינטימי, כאילו הוא יושב לידכם בחדר.''',
'''Rejoicing in the Hands היה אחד האלבומים שהחזירו את הפולק המוזר והחופשי של סוף שנות השישים לחיים. בנהארט השפיע על דור של זמרי פולק צעירים, והראה שגם הקלטה פשוטה עם גיטרה אחת יכולה להיות מלאה בקסם.''',
'''זה אלבום ללילה שקט, לבד או עם מישהו קרוב. אם אהבתם את Pink Moon של ניק דרייק (אלבום 262), תמצאו כאן רוח דומה, אבל משוגעת ומצחיקה יותר.''',
], [
('A Sight to Behold', 'שיר שקט ומרגש על יופי, עם גיטרה אקוסטית וקול רועד.'),
('This Beard Is for Siobhan', 'שיר שמח ומצחיק עם פסנתר, על זקן שהוא מגדל בשביל מישהי.'),
('The Body Breaks', 'שיר עדין ושקט שנשמע כמו תפילה קטנה, עם קול רועד ושביר.'),
])

add(984, [
'''ניק קייב, הזמר האוסטרלי שהכרנו כאן עם הבירת׳דיי פארטי ועם להקת הבאד סידז (אלבומים 509, 731, 828 ו־848), הוציא ב־2004 אלבום כפול: Abattoir Blues ו־The Lyre of Orpheus. זה היה האלבום הראשון של הבאד סידז בלי בליקסה ברגלד, הגיטריסט הוותיק שעזב, והלהקה נשמעת כאן משוחררת וחגיגית. הם הקליטו אותו בפריז, בזמן קצר מאוד, עם מקהלת גוספל מלונדון שמלווה כמעט כל שיר.''',
'''שני החצאים שונים: Abattoir Blues רועש, סוער ודתי, עם רוק גוספל עז, ו־The Lyre of Orpheus רך, שקט ורומנטי יותר. Get Ready for Love פותח את האלבום בפיצוץ של תופים, גיטרות ומקהלה, כמו טקס דתי מטורף. Nature Boy הוא שיר אהבה שמח וקליט, על נער שמגלה יופי בעולם. There She Goes, My Beautiful World הוא שיר מצחיק ונלהב על השראה, שמזכיר משוררים וסופרים מפורסמים. The Lyre of Orpheus הוא סיפור משעשע על אורפאוס מהמיתולוגיה היוונית, שממציא נבל ומשגע את אלוהים. Breathless הוא שיר אהבה פשוט ומאושר עם חליל, ו־O Children סוגר את האלבום בשיר שקט ומרגש על הדור הבא.''',
'''Abattoir Blues / The Lyre of Orpheus נחשב לאחד האלבומים הטובים של קייב, והראה שגם אחרי עשרים שנה של קריירה הוא יכול להפתיע ולהישמע צעיר. הוא הוכיח שאפשר לכתוב על אלוהים, מוות ואהבה בהומור, בשמחה ובלהט.''',
'''שמעו קודם את Get Ready for Love בקול רם, ואחר כך את Breathless, כדי לשמוע את שני הקצוות של האלבום. ואם אהבתם, חזרו ל־The Boatman's Call (אלבום 848), האלבום השקט והעצוב שלו.''',
], [
('Get Ready for Love', 'פתיחה סוערת עם תופים, גיטרות ומקהלת גוספל, כמו טקס דתי מטורף.'),
('Nature Boy', 'שיר אהבה שמח וקליט, על נער שמגלה יופי בעולם אכזר.'),
('Breathless', 'שיר אהבה פשוט ומאושר עם חליל, על טבע, שמש ואהבה.'),
])

add(985, [
'''פרנץ פרדיננד היא להקה מגלזגו שבסקוטלנד, שנקראת על שם הארכידוכס האוסטרי שרציחתו ב־1914 הציתה את מלחמת העולם הראשונה. הזמר אלכס קפרנוס והחברים שלו רצו לעשות "מוזיקה שבנות ירקדו לה", כלשונם, ולא עוד רוק רציני ועצוב. אלבום הבכורה שלהם, שנקרא פשוט Franz Ferdinand, יצא ב־2004, הגיע למקום השלישי בבריטניה, וזכה בפרס מרקורי. הם הפכו מהר מאוד לאחת הלהקות הכי מדוברות בעולם.''',
'''המוזיקה מחברת את הפוסט פאנק החד של סוף שנות השבעים, כמו גאנג אוף פור (אלבום 445) וטוקינג הדז (אלבום 382), עם פופ קליט ורקיד. הגיטרות חדות וקופצניות, התופים פשוטים ובטוחים, וקפרנוס שר בקול בריטי חלק עם הרבה הומור. Take Me Out, הלהיט הגדול, מתחיל בקצב מהיר ואז משנה פתאום כיוון לריף איטי ומפתה, וזה אחד המעברים המפורסמים בשירי הרוק של אותו עשור. The Dark of the Matinée מספר על נער שבורח מבית הספר, ו־Michael הוא שיר אהבה בין שני גברים על רחבת הריקודים. This Fire בוער ומתלהב, ו־Jacqueline פותח את האלבום בשקט ואז מתפוצץ.''',
'''Franz Ferdinand הוכיח שרוק גיטרות יכול להיות גם רקיד ומצחיק, והשפיע על גל שלם של להקות אינדי רקידות. Take Me Out נשאר אחד השירים המזוהים ביותר עם אמצע שנות האלפיים.''',
'''שמעו את Take Me Out ושימו לב לרגע שבו הקצב משתנה. אחר כך שמעו את Entertainment! של גאנג אוף פור (אלבום 445), ותשמעו מאיפה הגיטרות החדות הגיעו.''',
], [
('Take Me Out', 'הלהיט הגדול, עם המעבר המפורסם מקצב מהיר לריף איטי ומפתה.'),
('The Dark of the Matinée', 'שיר קופצני ומצחיק על נער שבורח מבית הספר לחלום בעיר.'),
('Michael', 'שיר אהבה רקיד בין שני גברים, עם גיטרות חדות ושירה חושנית.'),
])

add(986, [
'''N.E.R.D. היא להקה של פארל ויליאמס וצ׳אד הוגו, צמד ההפקה הנפטונז שהפיק בתחילת שנות האלפיים חלק עצום מלהיטי הפופ וההיפ הופ, כולל את Justified של ג׳סטין טימברלייק (אלבום 959), יחד עם חברם שיי היילי. בלהקה הם עושים מה שלא יכלו לעשות בשביל אחרים: רוק, פאנק ופופ בלי גבולות. Fly or Die, האלבום השני שלהם, יצא ב־2004, ובו הם החליטו לנגן בעצמם על כלים אמיתיים, גיטרות, תופים ופסנתר, גם אם עוד לא שלטו בהם לגמרי.''',
'''התוצאה היא תערובת משוגעת: רוק אלטרנטיבי, פאנק של שנות השבעים, היפ הופ, פופ של הביטלס ואפילו מעט סקייטפאנק. פארל שר בקול פלסטו גבוה ורך, והשירים מלאים הומור, אנרגיה ושינויי כיוון פתאומיים. She Wants to Move, הלהיט הגדול, הוא שיר ריקוד קופצני עם גיטרה פאנקית ופזמון קליט, על בחורה שכולם מסתכלים עליה ברחבה. Maybe הוא שיר רך ומלא נשמה עם פסנתר, שמזכיר סול של שנות השבעים. שיר הנושא, Fly or Die, הוא שיר רוק רועש עם פזמון גדול, שקורא להעז, ושירים אחרים קופצים בין פאנק, רוק ובלדות.''',
'''Fly or Die לא הצליח כמו הלהיטים שהנפטונז הפיקו לאחרים, אבל הוא הראה את הצד הסקרן והשובב שלהם, וחיזק את הקשר בין היפ הופ לרוק בשנות האלפיים. פארל המשיך להיות אחד האמנים המשפיעים ביותר בעולם הפופ.''',
'''שמעו את She Wants to Move ואת Maybe, ואחר כך השוו ל־Rock Your Body של טימברלייק (אלבום 959), ותשמעו את אותם מפיקים בשני תפקידים שונים.''',
], [
('She Wants to Move', 'שיר ריקוד קופצני עם גיטרה פאנקית, הלהיט הגדול של הלהקה.'),
('Maybe', 'שיר רך ומלא נשמה עם פסנתר, שמזכיר סול של שנות השבעים.'),
('Fly or Die', 'שיר הנושא, רוק רועש עם פזמון גדול שקורא להעז ולעוף.'),
])

add(987, [
'''הביטא בנד היא להקה סקוטית שהכרנו כבר עם Hot Shots II (אלבום 939). היא נודעה בצליל המוזר שלה, שמשלב פולק, היפ הופ, פסיכדליה ומוזיקה אלקטרונית, וברגע מפורסם בסרט "נאמנות גבוהה", שבו ג׳ון קיוזאק אומר שהוא עומד למכור חמישה עותקים של תקליט שלה, ומשמיע אותו בחנות. Heroes to Zeros, שיצא ב־2004, הוא האלבום השלישי והאחרון שלהם: זמן קצר אחרי צאתו הודיעה הלהקה על פירוקה, וחילקה את סיבוב ההופעות האחרון שלה כפרידה.''',
'''הזמר סטיב מייסון והחברים שלו רצו הפעם להישמע ישירים יותר, כמו להקת רוק של ממש, אחרי שנים של ניסויים. השירים בנויים על קצב חזק, גיטרות, סינתיסייזרים וקולות שכבות, עם מלודיות קליטות יותר מבעבר. Assessment, הפותח, הוא שיר אנרגטי וסוחף שנבנה לשיא גדול. Out-Side קופצני ושמח, עם פזמון שנשאר בראש, ו־Wonderful הוא שיר עדין ונוגה יותר. גם כשהשירים נשמעים פשוטים, יש בהם הרבה פרטים קטנים: צלילים מוזרים, הקלטות מהרחוב ומעברים מפתיעים.''',
'''Heroes to Zeros סגר את הקריירה של הביטא בנד בשיא יצירתי, למרות שלא הצליח מסחרית. הלהקה השפיעה על להקות רבות, ובהן קולדפליי, שחבריה דיברו בגלוי על ההשפעה, ומייסון המשיך לקריירת סולו מוערכת.''',
'''שמעו את Assessment בקול רם, ואחר כך חזרו ל־Hot Shots II (אלבום 939) כדי לשמוע איך הלהקה התפתחה מצליל רך ומרחף לרוק חזק וברור.''',
], [
('Assessment', 'פתיחה אנרגטית וסוחפת, שנבנית לאט לשיא גדול ושמח.'),
('Out-Side', 'שיר קופצני ושמח עם פזמון שנשאר בראש הרבה אחרי שנגמר.'),
('Wonderful', 'שיר עדין ונוגה, שמראה את הצד השקט והמהורהר של הלהקה.'),
])

add(988, [
'''אוזומטלי היא להקה מלוס אנג׳לס, שנולדה ב־1995 מתוך מאבק של עובדים במרכז קהילתי, ומאז היא שילוב של מוזיקאים ממוצא מקסיקני, אפריקאי־אמריקאי, יפני ועוד. הלהקה ידועה בהופעות שמחות ופוליטיות, שבהן הנגנים יורדים לפעמים מהבמה ומנגנים בתוך הקהל. Street Signs, שיצא ב־2004, הוא האלבום הרביעי שלהם, וזכה בפרס גראמי לאלבום הרוק הלטיני או האלטרנטיבי הטוב ביותר.''',
'''המוזיקה של אוזומטלי היא כמו שכונה בלוס אנג׳לס: סלסה, קומביה, היפ הופ, פאנק, רגאיי, רוק ולפעמים גם צלילים מהמזרח התיכון וצפון אפריקה, הכל בתוך שיר אחד. יש כאן כלי נשיפה, כלי הקשה לטיניים, ראפ באנגלית ובספרדית, ושירה משותפת של כל הלהקה. Believe פותח את האלבום עם צלילים מזרחיים ותופים, ו־Who Discovered America? שואל בהומור ובזעם מי באמת גילה את אמריקה. Saturday Night הוא שיר מסיבה שמח ופשוט, ו־Te Estoy Buscando הוא סלסה חמה ורקידה. כמה מהשירים מדברים על מהגרים, על עוני ועל צדק, אבל תמיד עם קצב שגורם לרקוד.''',
'''Street Signs הראה שמוזיקה פוליטית יכולה להיות גם שמחה, ושאפשר לחבר תרבויות שונות בלי לאבד את הזהות של כל אחת מהן. אוזומטלי נשארו להקה אהובה מאוד, במיוחד בהופעות חיות.''',
'''זה אלבום מושלם למסיבה בבית או לנסיעה בקיץ. שמעו את Saturday Night ואת Who Discovered America?, ואחר כך את Blue Lines של מאסיב אטאק (אלבום 704) כדי לשמוע עוד דרך לחבר בין עולמות.''',
], [
('Believe', 'פתיחה עם צלילים מזרחיים, כלי נשיפה ותופים, שמחה ומרגשת.'),
('Who Discovered America?', 'שיר מצחיק וזועם ששואל מי באמת גילה את אמריקה.'),
('Saturday Night', 'שיר מסיבה שמח ופשוט, עם כלי נשיפה ופזמון שכולם שרים.'),
])

add(989, [
'''הליברטינז הם להקה מלונדון, שבמרכזה שני חברים, כותבי שירים וזמרים: פיט דוהרטי וקרל בארה. הם חלמו על אנגליה רומנטית של משוררים, פאבים ושירי עם, ואלבום הבכורה שלהם, Up the Bracket, הפך אותם לגיבורי רוק צעירים. אבל עד 2004 דוהרטי היה מכור לסמים, פרץ לדירה של בארה ואפילו ישב בכלא לזמן קצר, והלהקה כמעט התפרקה. האלבום השני, שנקרא פשוט The Libertines, יצא באוגוסט 2004, הגיע למקום הראשון בבריטניה, והוא בעצם יומן של חברות שמתפרקת.''',
'''את האלבום הפיק מיק ג׳ונס, הגיטריסט של הקלאש (אלבומים 377 ו־439), שהפיק גם את הראשון. הצליל רועש, מהיר ומעט מרושל, כמו הופעה בפאב: גיטרות פאנק, תופים פשוטים ושני זמרים שמתחלפים. Can't Stand Me Now, השיר הפותח, הוא דו־שיח בין דוהרטי לבארה, שבו הם מאשימים זה את זה ועדיין שרים יחד, והוא אחד משירי הפרידה הכי אמיתיים ברוק. What Became of the Likely Lads שואל מה קרה לשני הנערים שחלמו יחד, ו־Music When the Lights Go Out הוא שיר עצוב ושקט על אהבה שנגמרה. Don't Be Shy ו־The Man Who Would Be King מלאים אנרגיה והומור.''',
'''The Libertines סגר את הפרק הראשון של הלהקה: היא התפרקה זמן קצר אחר כך, ודוהרטי הפך לדמות מוכרת בצהובונים. אבל הליברטינז השפיעו על דור שלם של להקות בריטיות, מארקטיק מאנקיז ועד היום, והחזירו לרוק הבריטי את הרומנטיקה.''',
'''שמעו את Can't Stand Me Now ושימו לב לשתי השירות. אחר כך שמעו את London Calling של הקלאש (אלבום 439), כדי לשמוע את המפיק בתור מוזיקאי צעיר.''',
], [
("Can't Stand Me Now", 'דו־שיח בין שני חברים שמאשימים זה את זה ועדיין שרים יחד.'),
('What Became of the Likely Lads', 'שאלה נוגה ומלאת אנרגיה על מה קרה לשני הנערים שחלמו יחד.'),
('Music When the Lights Go Out', 'שיר עצוב ושקט עם גיטרה אקוסטית, על אהבה שנגמרה.'),
])

add(990, [
'''קניה ווסט משיקגו התחיל כמפיק: הוא יצר ביטים לראפרים אחרים, ובעיקר לג׳יי זי, שעל The Blueprint שלו (אלבום 940) הוא עבד. אבל הוא רצה להיות ראפר בעצמו, ואף אחד לא לקח אותו ברצינות, כי לא נראה ולא נשמע כמו ראפר של רחוב. באוקטובר 2002 הוא נפצע בתאונת דרכים קשה, ולסת שלו נשברה. שבועיים אחר כך, כשהלסת עוד הייתה קשורה בחוטים, הוא הקליט את Through the Wire, שיר על התאונה, וזה הפך לסינגל הראשון שלו. The College Dropout, אלבום הבכורה, יצא בתחילת 2004.''',
'''השם, "הנושר מהקולג׳", מדבר על ההחלטה של קניה לעזוב את הלימודים כדי לעשות מוזיקה, ועל הלחץ החברתי ללכת בדרך הבטוחה. הביטים שלו בנויים על דגימות מואצות של שירי סול ישנים, שנשמעות כמו קולות של שדונים קטנים, יחד עם מקהלות גוספל, פסנתר וכלי מיתר. Through the Wire בנוי על דגימה מואצת של Through the Fire של צ׳אקה קאן. Jesus Walks הוא שיר גוספל עם תופי צעדה ומקהלה, על אמונה בעולם אלים, ונחשב לנועז מאוד בזמנו. All Falls Down, שבנוי על שיר של לורין היל (אלבום 870), מדבר על חומרנות וחוסר ביטחון בעצמו. Slow Jamz הוא שיר מצחיק ורומנטי על שירי אהבה ישנים.''',
'''The College Dropout זכה בפרס גראמי לאלבום הראפ הטוב ביותר, והפך את קניה ווסט לאחד האמנים החשובים והמשפיעים של המאה העשרים ואחת. הוא הוכיח שראפר יכול לדבר על אמונה, משפחה וחוסר ביטחון, ולא רק על רחוב וכסף.''',
'''שמעו את Through the Wire ונסו לשמוע את הלסת הקשורה בקול שלו. אחר כך שמעו את Jesus Walks בקול רם, כדי להרגיש את תופי הצעדה.''',
], [
('Through the Wire', 'שיר על תאונת הדרכים, שהוקלט כשהלסת שלו עוד הייתה קשורה בחוטים.'),
('Jesus Walks', 'שיר גוספל עם תופי צעדה ומקהלה, על אמונה בעולם אלים וקשה.'),
('All Falls Down', 'שיר כן ומצחיק על חומרנות וחוסר ביטחון, עם קול נשי רך.'),
])

add(991, [
'''סי־לו גרין, ששמו האמיתי תומאס קאלוויי, גדל באטלנטה והיה חבר בגודי מוב, להקת היפ הופ מאותה משפחה מוזיקלית של אאוטקאסט (אלבומים 928 ו־971). הוא ידוע בקול יוצא דופן: גבוה, צרוד ומלא נשמה, שמסוגל גם לראפ מהיר וגם לשירת סול כמו של כומר בכנסייה. Cee-Lo Green... Is the Soul Machine, אלבום הסולו השני שלו, יצא ב־2004, ובו הוא מנסה לחבר בין כל הצדדים שלו: ראפר, זמר, מטיף וליצן. כמה שנים אחר כך הוא הפך לכוכב עולמי עם Crazy של גנרלס בארקלי.''',
'''את האלבום הפיקו כמה מהמפיקים הגדולים של התקופה, ובהם טימבלנד, כך שכל שיר נשמע אחרת. יש כאן היפ הופ דרומי כבד, סול של שנות השבעים, גוספל ופאנק. I'll Be Around, בהפקת טימבלנד, הוא שיר מקפץ עם ביט מוזר ופזמון קליט. סי־לו קופץ בין ראפ מהיר מאוד לבין שירה מלאה, ולפעמים עושה את שניהם באותו שיר. הוא שר על אלוהים, על אהבה, על כסף ועל עצמו, עם הרבה הומור והגזמה מכוונת. יש שירים עליזים שנועדו לריקוד, ויש בלדות איטיות שבהן הקול שלו מגיע לשיאים של זמרי סול גדולים כמו אל גרין וקרטיס מייפילד.''',
'''Is the Soul Machine לא היה הצלחה מסחרית גדולה, אבל הוא הראה כמה גדול הכישרון של סי־לו, והכין את הקרקע לקריירה המצליחה שלו כזמר פופ וסול. הוא גם אחד הניסיונות המעניינים לחבר בין היפ הופ לסול הישן.''',
'''שמעו את I'll Be Around, ואחר כך בחרו בלדה איטית ושימו לב לקול. אם אהבתם, שמעו את The Love Below של אאוטקאסט (אלבום 971), שגם בו ראפר הופך לזמר.''',
], [
])

add(992, [
'''טי וי און דה רדיו היא להקה מברוקלין שבניו יורק, שהוקמה על ידי הזמר טונדה אדבימפה, שהיה גם אמן אנימציה, והמפיק והמוזיקאי דייוויד סיטק, שהפיק גם את Fever to Tell של ייה ייה ייהז (אלבום 970). אליהם הצטרף הזמר והגיטריסט קיפ מאלון, עם קול פלסטו גבוה וזקן ענק. Desperate Youth, Blood Thirsty Babes, אלבום הבכורה המלא שלהם, יצא ב־2004, ומבקרים התלהבו ממנו מיד. הוא זכה בפרס חשוב למוזיקה חדשה באמריקה, ושם את הלהקה במרכז סצנת ברוקלין.''',
'''המוזיקה של הלהקה מערבבת דברים שלא אמורים להתאים: רעש של גיטרות ומכונות, דו־וופ וסול של שנות החמישים, פוסט פאנק, ג׳אז ומוזיקה אלקטרונית. שני הזמרים, אדבימפה ומאלון, שרים יחד הרמוניות עמוקות וגבוהות, כמו להקת סול ישנה בתוך סערה. Staring at the Sun, הלהיט הראשון, הוא שיר מתוח ויפה עם ביט חוזר ומהפנט. Ambulance הוא שיר א־קפלה, רק קולות בלי כלים, בסגנון דו־וופ, ומרגש מאוד. The Wrong Way פותח עם כלי נשיפה עמוקים ומדבר על גזענות ועל הזהות של צעירים שחורים באמריקה. Dreams עדין ונוגה, ו־King Eternal מתפוצץ בעוצמה.''',
'''Desperate Youth, Blood Thirsty Babes הפך את טי וי און דה רדיו לאחת הלהקות המשפיעות של שנות האלפיים. דייוויד בואי, שאהב את הלהקה, אפילו שר איתם בשיר באלבום הבא שלהם.''',
'''שמעו את Ambulance באוזניות, כדי לשמוע את כל הקולות. אחר כך שמעו את Staring at the Sun, ושימו לב איך הלהקה בונה קיר של צליל מעט מאוד כלים.''',
], [
('Staring at the Sun', 'שיר מתוח ויפה עם ביט חוזר ומהפנט, הלהיט הראשון של הלהקה.'),
('Ambulance', 'שיר א־קפלה מרגש, רק קולות בלי כלים, בסגנון הדו־וופ של שנות החמישים.'),
('The Wrong Way', 'פתיחה עם כלי נשיפה עמוקים, על זהות וגזענות באמריקה.'),
])

add(993, [
'''לייארס היא להקה שנוסדה בלוס אנג׳לס ופעלה בניו יורק, בהובלת הזמר האוסטרלי הגבוה אנגוס אנדרו והמוזיקאי אהרון המפיל. אלבום הבכורה שלהם היה פוסט פאנק רקיד, שהתאים לסצנה של ייה ייה ייהז (אלבום 970) והסטרוקס. אבל באלבום השני, They Were Wrong, So We Drowned, שיצא ב־2004, הם הפתיעו את כולם: זה אלבום קונספט אפל, רועש ומוזר על מכשפות, על ציד מכשפות ועל ליל ולפורגיס, הלילה שבו לפי האגדה הגרמנית המכשפות מתכנסות על הר ברוקן.''',
'''במקום שירי ריקוד, יש כאן תופים כבדים וחוזרים, רעש של גיטרות ומכונות, קולות של מקהלה מפחידה ושירה מוזרה, לפעמים לחישה ולפעמים צעקה. השם של האלבום מתייחס לדרך ישנה ואכזרית לבחון אם אישה היא מכשפה: זורקים אותה למים, ואם היא טובעת, סימן שהיא חפה מפשע. There's Always Room on the Broom הוא שיר קצבי עם תופים טקסיים ושירה מוזרה, ו־Broken Witch מלא בצעקות של מקהלה מאיימת. שמות השירים ארוכים ומשונים, כמו כותרות של אגדות. הכל נשמע כמו טקס ביער בלילה, מבהיל ומהפנט בו בזמן.''',
'''They Were Wrong, So We Drowned קיבל ביקורות קשות מאוד בזמנו, וחלק מהמבקרים פשוט לא הבינו מה הלהקה מנסה לעשות. אבל עם השנים הוא הפך לאלבום מוערך, והוכיח שלייארס מוכנים להסתכן ולשנות כיוון בכל פעם.''',
'''זה אלבום קשה, אז שמעו אותו בלילה, באוזניות, כמו סיפור אימה. אם אתם רוצים משהו קליל יותר, שמעו קודם את Maps של ייה ייה ייהז (אלבום 970), שלפי הדיווחים נכתב לאנגוס אנדרו.''',
], [
])

add(994, [
'''הסטריטס הוא בעצם אדם אחד: מייק סקינר מבירמינגהם, שעבר ללונדון ועשה היפ הופ בריטי שנשמע כמו שיחה בפאב. באלבום הראשון שלו, Original Pirate Material, הוא תיאר את חיי הצעירים בבריטניה בדייקנות ובהומור. A Grand Don't Come for Free, שיצא ב־2004, שאפתני יותר: זה אלבום קונספט שמספר סיפור אחד, מהתחלה ועד הסוף, כמו סרט. הוא הגיע למקום הראשון בבריטניה, ו־Dry Your Eyes ממנו הגיע למקום הראשון במצעד הסינגלים.''',
'''הסיפור פשוט ויומיומי: מייק מאבד אלף ליש״ט, "גרנד" בסלנג, ובמהלך האלבום מנסה למצוא אותם, נפגש עם בחורה בשם סימון, מתאהב בה, מהמר על משחק כדורגל, מבלה עם חברים ומגלה שבגדו בו. סקינר מספר את כל זה כמעט בדיבור, במבטא כבד, על ביטים פשוטים, פסנתר וכלי מיתר. It Was Supposed to Be So Easy פותח ביום שבו הכל משתבש: הכסף נעלם, הטלוויזיה לא עובדת והבנק לא עונה. Fit but You Know It הוא שיר מצחיק ומהיר עם גיטרות, על בחורה יפה בחופשה. Blinded by the Lights מתאר לילה מבולבל במועדון, ו־Dry Your Eyes הוא שיר פרידה עצוב ומרגש, עם גיטרה אקוסטית וכלי מיתר, שגרם להרבה גברים בריטיים לבכות.''',
'''A Grand Don't Come for Free הוכיח שאפשר לספר סיפור שלם באלבום היפ הופ, עם רגשות, הומור ופרטים קטנים מהחיים, בלי גיבורי־על ובלי אלימות. הוא נחשב לאחד האלבומים הבריטיים החשובים של העשור.''',
'''שמעו את האלבום ברצף, מההתחלה ועד הסוף, כמו סרט, כי הסיום מפתיע. ואם אהבתם את Boy in da Corner של דיזי רסקל (אלבום 967), תשמעו כאן את הצד הרך והמצחיק של לונדון.''',
], [
('It Was Supposed to Be So Easy', 'פתיחה מצחיקה ליום שבו הכל משתבש, והכסף נעלם בלי עקבות.'),
('Fit but You Know It', 'שיר מהיר ומצחיק עם גיטרות, על בחורה יפה בחופשה.'),
('Dry Your Eyes', 'שיר פרידה עצוב ומרגש עם גיטרה אקוסטית, שהגיע למקום הראשון.'),
])

add(995, [
'''Want Two הוא החצי השני של הפרויקט הכפול של רופוס ויינרייט, שהתחיל ב־Want One (אלבום 975). הוא יצא בסוף 2004, והוקלט באותן הפקות עם מריוס דה פריס. אם Want One היה החצי הפופי והשמח יותר, Want Two אפל, דרמטי ואישי יותר, והוא מלא אופרה, דת, מיתולוגיה וקבלה עצמית. על העטיפה ויינרייט מצולם כאישה מימי הביניים, כמו דמות מאגדה, והאלבום נשמע כמו מסע דרך גיהינום ובחזרה.''',
'''Agnus Dei, השיר הפותח, הוא תפילה לטינית עם כלי מיתר ותופים מזרחיים, מסתורי ויפה. The Art Teacher, שהוקלט בהופעה חיה, מספר מנקודת המבט של אישה מבוגרת שנזכרת באהבה שלה, כנערה, למורה לאמנות, שלא ידע עליה מעולם, והוא אחד השירים הכי נוגעים ללב שכתב. Memphis Skyline הוא שיר לזכרו של ג׳ף באקלי (אלבום 780), שמת בממפיס ב־1997, ומתאר את הקנאה ואת האהבה שהרגיש כלפיו. Gay Messiah הוא שיר פרובוקטיבי ומצחיק, ו־Little Sister מוקדש לאחותו הזמרת מרתה ויינרייט, וכולל קטע בסגנון מוצרט.''',
'''Want Two נחשב לחצי העמוק והמאתגר מהשניים, ורבים מעדיפים אותו דווקא בגלל זה. יחד, שני האלבומים הם אחד ההישגים הגדולים של ויינרייט, וחיבור נדיר בין אופרה, פופ ושירה אישית מאוד.''',
'''שמעו את The Art Teacher בשקט, ותנו לסיפור לגעת בכם. אחר כך שמעו את Memphis Skyline, ואת Hallelujah בגרסה של ג׳ף באקלי מ־Grace (אלבום 780). רופוס עצמו הקליט גם הוא גרסה מפורסמת לאותו שיר.''',
], [
('The Art Teacher', 'אישה מבוגרת נזכרת באהבה שלה, כנערה, למורה לאמנות שלא ידע עליה.'),
('Memphis Skyline', 'שיר מרגש לזכרו של ג׳ף באקלי, על קנאה, אהבה ואובדן.'),
('Agnus Dei', 'תפילה לטינית מסתורית עם כלי מיתר ותופים מזרחיים.'),
])

add(996, [
'''הזוטונז הם להקה מליברפול, שבראשה עומד הזמר והגיטריסט דייב מקייב, ולצידו נגנית הסקסופון אבי הרדינג, דבר נדיר בלהקות רוק בריטיות של אותה תקופה. הם ניגנו רוק עם השפעות של בלוז, סול, פאנק וגראז׳, והיו ידועים בהופעות שמחות ומלאות אנרגיה. Who Killed...... The Zutons?, אלבום הבכורה שלהם, יצא ב־2004, והיה מועמד לפרס מרקורי. השם המוזר, "מי הרג את הזוטונז?", מתאים ללהקה שאוהבת סיפורי מתח, רוחות רפאים ודמויות מוזרות.''',
'''השירים קצביים וקופצניים, עם גיטרות חדות, סקסופון שמוסיף צבע של סול ופאנק, ופזמונים שקל לשיר יחד. מקייב שר בקול צרוד ומלא אופי, לפעמים כמעט צועק. Zuton Fever הוא שיר פתיחה מקפץ, כמעט הצגה של הלהקה. Pressure Point, הלהיט הגדול, בנוי על ריף גיטרה עקשני ועל סקסופון, ומדבר על לחץ שגורם לאדם להתפוצץ. You Will You Won't הוא שיר פופ קליט על החלטות, ו־Confusion ו־Remember Me מלאים אנרגיה. Havana Gang Brawl נשמע כמו סצנה מסרט פשע. הכל נשמע כמו מסיבה בפאב בליברפול, עם קריצה לרוק של שנות השישים והשבעים.''',
'''Who Killed...... The Zutons? לא הפך את הזוטונז לכוכבים גדולים, אבל הוא הציג להקה מקורית ושמחה. באלבום הבא שלהם הופיע השיר Valerie, שהפך שנים אחר כך ללהיט ענק בגרסה של מארק רונסון ואיימי ויינהאוס (אלבום 963).''',
'''שמעו את Pressure Point בקול רם, ושימו לב איך הסקסופון והגיטרה משחקים יחד. זה אלבום מושלם לניקיון בבית או למסיבה קטנה עם חברים.''',
], [
('Zuton Fever', 'שיר פתיחה מקפץ שמציג את הלהקה, עם סקסופון וגיטרות חדות.'),
('Pressure Point', 'הלהיט הגדול, עם ריף עקשני וסקסופון, על לחץ שגורם להתפוצץ.'),
("You Will You Won't", 'שיר פופ קליט על החלטות קשות, עם פזמון שקל לשיר יחד.'),
])

add(997, [
'''הקילרז הם להקה מלאס וגאס, עיר הקזינו של המדבר, שבה הזמר ברנדון פלאוורס עבד כשליח בבית מלון לפני שהפך לכוכב. פלאוורס אהב מאוד להקות בריטיות של שנות השמונים, כמו ניו אורדר (אלבום 561), הסמית׳ס (אלבום 584) ודוראן דוראן (אלבום 514), ומשם הגיע הצליל של הלהקה. Hot Fuss, אלבום הבכורה שלהם, יצא ב־2004, והצליח קודם כל בבריטניה, לפני שארצות הברית שמה לב. בסופו של דבר נמכר במיליוני עותקים והפך לאחד מאלבומי הבכורה הגדולים של העשור.''',
'''המוזיקה היא רוק עם סינתיסייזרים, גיטרות מהדהדות ופזמונים ענקיים, שנועדו לשירה משותפת באצטדיונים. Mr. Brightside, הלהיט הגדול, הוא שיר על קנאה, שפלאוורס כתב אחרי שגילה שחברתו בוגדת בו. השיר נשאר במצעד הבריטי שנים רבות יותר מכל שיר אחר, ועד היום שרים אותו בכל מסיבה. Somebody Told Me הוא שיר ריקוד מהיר עם סינתיסייזר, על בלבול רומנטי במועדון. All These Things That I've Done נבנה בהדרגה לשיא עם מקהלת גוספל, והשורה "יש לי נשמה, אבל אני לא חייל" הפכה לקריאה של קהלים. Smile Like You Mean It נוגה ויפה, ו־Jenny Was a Friend of Mine מספר סיפור מתח קטן.''',
'''Hot Fuss הפך את הקילרז לאחת הלהקות הגדולות של שנות האלפיים, והחזיר את הסינתיסייזרים של שנות השמונים לרוק. Mr. Brightside נחשב לאחד השירים המזוהים ביותר עם העשור כולו.''',
'''שמעו את Mr. Brightside, ואחר כך את All These Things That I've Done עד הסוף, כדי לשמוע את המקהלה. אם אהבתם, נסו את Low-Life של ניו אורדר (אלבום 561), ותבינו מאיפה זה בא.''',
], [
('Mr. Brightside', 'שיר על קנאה, שנשאר במצעד הבריטי שנים ושרים אותו בכל מסיבה.'),
("All These Things That I've Done", 'שיר שנבנה לאט לשיא עם מקהלת גוספל ושורה שכולם צועקים.'),
('Somebody Told Me', 'שיר ריקוד מהיר עם סינתיסייזר, על בלבול רומנטי במועדון.'),
])

add(998, [
'''קינגס אוף לאון, המשפחה מטנסי שהכרנו באלבום 968, חזרו ב־2004, פחות משנה וחצי אחרי אלבום הבכורה, עם Aha Shake Heartbreak. בינתיים הם הופיעו בכל העולם, חיממו להקות גדולות והפכו לכוכבים בבריטניה, והשינוי ניכר: השירים מחוספסים, פרועים ואישיים יותר, ומלאים בסיפורים על לילות ארוכים, נשים, מסיבות ותהילה מהירה מדי. גם כאן הפיקו איתן ג׳ונס ואנג׳לו פטרגליה, והאלבום הגיע לטופ 3 בבריטניה.''',
'''הקול של קיילב פולוויל נשמע כאן עוד יותר ממלמל וצרוד, כאילו הוא שר אחרי לילה בלי שינה, והגיטרות משחקות אחת עם השנייה בצורה חופשית ועצבנית. The Bucket הוא שיר קצבי וקליט עם גיטרות מתפתלות ופזמון מתגעגע, והיה ללהיט באנגליה. Four Kicks הוא שיר קצר ומהיר על קטטה בבר, ו־King of the Rodeo נשמע כמו מסיבה פרועה במערב. Milk הוא שיר איטי ועצוב, עם גיטרה שקטה וקול שבור, ו־Slow Night, So Long פותח את האלבום בקצב משתנה ומפתיע. Day Old Blues הוא שיר אקוסטי ומתגעגע, כמעט בלוז ישן.''',
'''Aha Shake Heartbreak נחשב בעיני מעריצים רבים לאלבום הטוב ביותר של הלהקה, לפני שהפכה לענקית אצטדיונים. הוא תופס את הרגע שבו להקה צעירה מהדרום מגלה את העולם, ואת המחיר שלו.''',
'''שמעו את The Bucket ואת Milk אחד אחרי השני, כדי לשמוע את שני הצדדים של הלהקה. ואחר כך השוו ל־Youth & Young Manhood (אלבום 968), ותשמעו כמה הם השתנו בשנה וחצי.''',
], [
('The Bucket', 'שיר קצבי וקליט עם גיטרות מתפתלות, שהיה ללהיט גדול באנגליה.'),
('Four Kicks', 'שיר קצר ומהיר על קטטה בבר, מלא אנרגיה והומור.'),
('Milk', 'שיר איטי ועצוב, עם גיטרה שקטה וקול שבור ומרגש.'),
])

add(999, [
'''מ.י.א., ששמה האמיתי מתנגי "מאיה" ארולפרגסם, נולדה בלונדון למשפחה טמילית מסרי לנקה, וגדלה בילדותה בסרי לנקה ובהודו, בזמן מלחמת האזרחים הקשה שם. כשהייתה בת אחת עשרה הגיעה עם אמה ואחיה ללונדון כפליטים, וגדלה בשיכון עני. היא למדה אמנות וקולנוע, ורק אחר כך התחילה לעשות מוזיקה, עם מכונת תופים קטנה. Arular, אלבום הבכורה שלה, יצא ב־2005, והוא נקרא על שם הכינוי הפוליטי של אביה, שהיה פעיל בתנועה הטמילית.''',
'''המוזיקה של מ.י.א. היא תערובת שלא נשמעה קודם: היפ הופ, דאנסהול ג׳מייקני, באילה פאנק מברזיל, אלקטרו, פאנק ומוזיקה מדרום אסיה, הכל עם ביטים חשופים ורועשים וצלילים זולים בכוונה, כמו של צעצועים. בין המפיקים היו דיפלו וסוויץ׳, שהפכו מאוחר יותר למפיקים מבוקשים מאוד. מ.י.א. ראפ בקול שובב ומתגרה, ומערבבת בין שירי מסיבה לבין מילים על מלחמה, פליטות ועוני. Galang, הסינגל הראשון, הוא שיר ריקוד מוזר וקליט, עם סלנג לונדוני. Sunshowers משלב קצב קריבי עם מילים על אלימות ופחד, ו־Bucky Done Gun בנוי על באילה פאנק ברזילאי ועל כלי נשיפה שמזכירים פסקול של סרט אקשן.''',
'''Arular הפך את מ.י.א. לאחת האמניות המשפיעות של שנות האלפיים. היא הראתה שמוזיקת פופ יכולה להגיע משכונות עניות ומארצות רחוקות, ולערבב את כל העולם לתוך שיר אחד. רבים רואים בה את הקול הראשון של עולם גלובלי ומחובר.''',
'''שמעו את Galang ואת Bucky Done Gun בקול רם, ונסו לזהות את כל הסגנונות שמתערבבים בהם. זה אלבום שמתאים למסיבה, אבל כדאי גם להקשיב למילים.''',
], [
('Galang', 'הסינגל הראשון, שיר ריקוד מוזר וקליט עם סלנג לונדוני וביט חשוף.'),
('Sunshowers', 'קצב קריבי שמח, עם מילים על פחד ואלימות בעולם.'),
('Bucky Done Gun', 'באילה פאנק ברזילאי עם כלי נשיפה, כמו פסקול של סרט אקשן.'),
])

add(1000, [
'''בק, שהכרנו כאן עם Odelay (אלבום 814) ועם Sea Change השקט והעצוב (אלבום 958), חזר ב־2005 עם Guero, ואיתו חזרו גם הדאסט ברדרז, צמד המפיקים שעבד איתו על Odelay. השם, "גוארו", הוא כינוי בספרדית מקסיקנית לבחור בהיר שיער ועור, וכך קראו לבק כשגדל בשכונה לטינית בלוס אנג׳לס. האלבום חוזר לשכונה הזו, לרחובות, לשמש ולמוזיקה שבק שמע כשהיה ילד: היפ הופ, בלוז, פולק, מוזיקה לטינית ורוק.''',
'''כמו ב־Odelay, השירים בנויים כמו קולאז׳: דגימות, ביטים, גיטרות, כלים מוזרים, ומשחקי מילים מצחיקים. E-Pro, הלהיט הגדול, נפתח בריף גיטרה רועש ובתופים כבדים, ופזמון של "נה נה נה" שקל לשיר. Qué Onda Guero הוא שיר היפ הופ מצחיק שבו בק מתאר את השכונה הלטינית שלו, עם קולות של אנשים ברחוב ומילים בספרדית. Girl הוא שיר פופ שמח וקליט, שמסתיר מילים אפלות יותר. Missing משלב בוסה נובה ברזילאית ועצב, ו־Earthquake Weather הוא שיר קיצי ורגוע. ג׳ק וייט מהווייט סטרייפס (אלבומים 938 ו־966) מנגן בבס באחד השירים, Go It Alone.''',
'''Guero לא חידש כמו Odelay, אבל הוא אלבום שמח ובטוח בעצמו, שהזכיר לכולם כמה בק כיפי ומקורי. הוא זכה להצלחה גדולה ולמועמדויות לפרסי גראמי, והראה שבק מסוגל לחזור לכל אחד מהסגנונות שלו מתי שירצה.''',
'''שמעו את E-Pro בקול רם, ואחר כך את Qué Onda Guero. ואם בא לכם השוואה מעניינת, שמעו שיר מ־Sea Change (אלבום 958) מיד אחרי, ותשמעו את שני הקצוות של אותו אמן.''',
], [
('E-Pro', 'הלהיט הגדול, עם ריף גיטרה רועש, תופים כבדים ופזמון "נה נה נה" קליט.'),
('Qué Onda Guero', 'שיר היפ הופ מצחיק על השכונה הלטינית של בק, עם קולות מהרחוב.'),
('Girl', 'שיר פופ שמח וקליט, שמסתיר מתחת לשמחה מילים אפלות יותר.'),
])

add(1001, [
'''הגענו לאלבום האחרון ברשימה. הווייט סטרייפס, הצמד מדטרויט שהכרנו כבר פעמיים (אלבומים 938 ו־966), הוציאו את Get Behind Me Satan ב־2005, שנתיים אחרי Elephant, שהפך אותם לכוכבים. הפעם ג׳ק וייט החליט לשנות כיוון: במקום הגיטרה החשמלית הרועשת, רוב השירים כאן בנויים על פסנתר, מרימבה, גיטרה אקוסטית וכלי הקשה. הם הקליטו אותו מהר, תוך שבועיים בערך, באולפן בבית של ג׳ק בדטרויט. השם, "סור ממני, שטן", הוא ציטוט מהברית החדשה.''',
'''התוצאה מפתיעה ומגוונת. Blue Orchid, הסינגל הראשון והשיר היחיד שדומה לווייט סטרייפס הישנים, הוא שיר רוק קצר ועצבני עם גיטרה מעוותת וקול פלסטו גבוה. The Nurse נבנה על מרימבה עדינה, שנקטעת פתאום בהתפרצויות של תופים וגיטרה, כמו סיוט. My Doorbell הוא שיר שמח עם פסנתר, על מישהו שמחכה שיצלצלו לו בדלת. Little Ghost הוא שיר קאנטרי קצר ושמח, ו־As Ugly as I Seem הוא שיר אקוסטי נוגה. כמה שירים, כמו White Moon ו־Take, Take, Take, מוקדשים לשחקנית ההוליוודית ריטה הייוורת, שג׳ק היה מוקסם ממנה.''',
'''Get Behind Me Satan זכה בפרס גראמי לאלבום האלטרנטיבי הטוב ביותר, והראה שהווייט סטרייפס מסוגלים להמציא את עצמם מחדש. הוא גם סוגר את הרשימה של הספר, מסע של חמישים שנה שהתחיל עם פרנק סינטרה (אלבום 1) ומסתיים בצמד מדטרויט עם פסנתר ומרימבה.''',
'''שמעו את Blue Orchid ואת The Nurse, ואחר כך את My Doorbell. ואם הגעתם לכאן אחרי אלף אלבומים, מגיע לכם לשבת ולהקשיב לו עד הסוף.''',
], [
('Blue Orchid', 'שיר רוק קצר ועצבני עם גיטרה מעוותת וקול פלסטו גבוה.'),
('The Nurse', 'מרימבה עדינה שנקטעת פתאום בהתפרצויות של תופים וגיטרה, כמו סיוט.'),
('My Doorbell', 'שיר שמח עם פסנתר, על מישהו שמחכה שיצלצלו לו בדלת.'),
])
